var enc = new TextEncoder();

function hex(buf) {

  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");

}

__name(hex, "hex");

function hexToBytes(h) {

  const a = new Uint8Array(h.length / 2);

  for (let i = 0; i < a.length; i++) a[i] = parseInt(h.substr(i * 2, 2), 16);

  return a;

}

__name(hexToBytes, "hexToBytes");

function b64url(s) {

  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

}

__name(b64url, "b64url");

function b64urlDecode(s) {

  s = s.replace(/-/g, "+").replace(/_/g, "/");

  while (s.length % 4) s += "=";

  return atob(s);

}

__name(b64urlDecode, "b64urlDecode");

var ok = /* @__PURE__ */ __name((o) => new Response(JSON.stringify(o), { headers: { "Content-Type": "application/json; charset=utf-8" } }), "ok");

var err = /* @__PURE__ */ __name((c, m) => new Response(JSON.stringify({ error: m }), { status: c, headers: { "Content-Type": "application/json; charset=utf-8" } }), "err");

async function readBody(request) {

  try {

    return await request.json();

  } catch (e) {

    return {};

  }

}

__name(readBody, "readBody");

async function hashPw(password, saltHex) {

  const salt = saltHex || hex(crypto.getRandomValues(new Uint8Array(16)));

  const iter = 1e5;

  const key = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);

  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", salt: hexToBytes(salt), iterations: iter, hash: "SHA-256" }, key, 256);

  return `pbkdf2$${iter}$${salt}$${hex(bits)}`;

}

__name(hashPw, "hashPw");

function authOk(user) {

  return !!user.authorized && (!user.expiry || Number(user.expiry) > Date.now());

}

__name(authOk, "authOk");

function modAuthed(user, m) {

  let mods = {};

  try {

    mods = JSON.parse(user.modules || "{}");

  } catch (e) {

  }

  return authOk(user) && !!mods[m];

}

__name(modAuthed, "modAuthed");

