async function parseToken(t, secret) {

  try {

    const [sig, b64] = t.split(".");

    const p = b64urlDecode(b64);

    if (await hmacHex(p, secret) !== sig) return null;

    const parts = p.split("|");

    return { uid: parts[0], seq: Number(parts[2]) };

  } catch (e) {

    return null;

  }

}

