async function uidOf(request, env) {

  const pt = await parseToken((request.headers.get("authorization") || "").replace(/^Bearer\s+/i, ""), env.APP_SECRET);

  if (!pt) return null;

  const row = await env.DB.prepare("SELECT * FROM users WHERE id = ?").bind(pt.uid).first();

  if (!row) return null;

  if (Number(row.session_seq || 0) !== pt.seq) return null;

  return row;

}

