async function ensureSettings(DB) {

  await DB.prepare("CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT)").run();

}

async function getSetting(DB, k, def) {

  await ensureSettings(DB);

  const r = await DB.prepare("SELECT v FROM settings WHERE k = ?").bind(k).first();

  return r ? r.v : def;

}

async function setSetting(DB, k, v) {

  await ensureSettings(DB);

  await DB.prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v").bind(k, v).run();

}

async function ensureStats(DB) {

  await DB.prepare("CREATE TABLE IF NOT EXISTS stats (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT, ip TEXT, ua TEXT, ref TEXT, day TEXT, ts INTEGER)").run();

}

function clientIp(request) {

  return request.headers.get("cf-connecting-ip") || (request.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "";

}

async function logVisit(DB, request, path, day) {

  try {

    await ensureStats(DB);

    const ip = clientIp(request);

    const ua = request.headers.get("user-agent") || "";

    const ref = request.headers.get("referer") || "";

    await DB.prepare("INSERT INTO stats (path, ip, ua, ref, day, ts) VALUES (?, ?, ?, ?, ?, ?)").bind(path, ip, ua, ref, day, Date.now()).run();

  } catch (e) {

  }

}

async function isAdmin(request, env) {

  const pt = await parseToken((request.headers.get("authorization") || "").replace(/^Bearer\s+/i, ""), env.APP_SECRET);

  return !!(pt && pt.uid === "admin");

}

__name(isAdmin, "isAdmin");

function getDev(body, request) {

  const d = body && typeof body.device === "string" && body.device || (request.headers.get("x-device") || "");

  if (d) return d;

  const ip = request.headers.get("cf-connecting-ip") || (request.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "";

  const ua = request.headers.get("user-agent") || "";

  return "fb-" + simpleHash(ip + "|" + ua);

}

