function simpleHash(s) {

  let h = 2166136261;

  for (let i = 0; i < s.length; i++) {

    h ^= s.charCodeAt(i);

    h = Math.imul(h, 16777619);

  }

  return ("0000000" + (h >>> 0).toString(16)).slice(-8);

}

