var hchinese_link_default = {"product":"高考总复习衔接包（高中语文）","version":1,"units":[{"id":"hl1","title":"语言文字运用·字音字形与词语","grade_tag":"高考基础","summary":"高考语言文字运用占比高，重点攻克易错字音字形与易混成语，把“读音正确、字形无误、语境得当”三关一次打通。","points":[{"id":"p01","title":"易错字音：从语境记音","content":"蜚声（fēi）、稹实（zhèn）、强的弩（qiǎng）、的的确确（dì）、桴鼓（fú）、徇私（xùn）、祗敬（zhī）。记音要放入词语语境，不孤立记单字。"},{"id":"p02","title":"易错字形：从词义辨字","content":"再接再厉（非再励）、融会贯通（非汇）、相形见绌（非拙）、徇私舞弊（非循）、谈笑风生（非声）、甘拜下风（非败）。"},{"id":"p03","title":"易混成语：不刊之论","content":"“刊”指削除、修改，意为不可改动的言论（褒义）。常与“首当其冲”（最先受冲击）、“七月流火”（天气转凉）区分。"},{"id":"p04","title":"语境得体：成语褒贬与对象","content":"高考成语题重在“语境得当”。判别三步：①看对象（谁用）；②看语境（褒/贬）；③看搭配。如“蔚然成风”用于好的风气，不用于坏事。"}],"quiz":[{"id":"q01","stem":"下列加“”字读音正确的一项是（　）","options":["蜚（fěi）声","徇（xún）私","桴（fú）鼓","祗（zhǐ）敬"],"answer":2,"analysis":"桴读 fú；徇读 xùn；祗读 zhī；蜚读 fēi。"},{"id":"q02","stem":"下列词语没有错别字的一项是（　）","options":["再接再励","融汇贯通","相形见绌","循私舞弊"],"answer":2,"analysis":"绌读 chù，指不足，正确。"},{"id":"q03","stem":"“不刊之论”的“刊”意思是（　）","options":["刊登","削除、修改","刊物","评论"],"answer":1,"analysis":"“刊”指削除、修改。"},{"id":"q04","stem":"下列加“”成语使用恰当的一项是（　）","options":["他文人相轻，互为知己","这篇社论真是不刊之论","他甘拜下风，虚心求教","这幅画构图精巧，蔚然成风"],"answer":1,"analysis":"B 恰当。A“文人相轻”指互相轻视；C 甘拜下风指承认不如；D 蔚然成风指形成风气，不用于画。"},{"id":"q05","stem":"下列句子有语病的一项是（　）","options":["通过学习，使我提高了。","我们要发扬并继承传统。","他认真读书。","这本书很精彩。"],"answer":1,"analysis":"B 语序不当，应先继承再发扬。"},{"id":"q06","stem":"修辞判断：“月光如流水”是（　）","options":["比喻","拟人","夸张","排比"],"answer":0,"analysis":"以“流水”喻“月光”，是比喻。"},{"id":"q07","stem":"下列表达得体的一项是（　）","options":["请问您贵姓？","您是干什么的？","请问您是哪位？","你姓啥？"],"answer":0,"analysis":"“请问您贵姓？”最得体。"},{"id":"q08","stem":"补写：读书要静心，____________，更要持之以恒。","options":["更要虚心求教","更要广泛阅读","更要持之以恒","更要熟读精思"],"answer":0,"analysis":"与后文“更要持之以恒”并列，且与“静心”相承，选 A。"}]},{"id":"hl2","title":"古诗文默写与直接默写","grade_tag":"高考必考","summary":"直接默写与理解性默写是高考语文的送分题，必须做到“理解语境、精准书写、一字不差”。","points":[{"id":"p05","title":"直接默写：高频篇目","content":"《劝学》（青出于蓝、金就砺则利）、《师说》（传道受业解惑）、《赤壁赋》（寄蜉蝣于天地）、《念奴娇·赤壁怀古》（卷起千堆雪）、《琵琶行》（此时无声胜有声）、《登高》（百年多病独登台）。"},{"id":"p06","title":"理解性默写：抓语境提示","content":"理解性默写常给一句上句，要求填下句。要联系全诗情感与意象，如《离骚》“路漫漫其修远兮，吾将上下而”填“求索”，须理解诗人求索志向。"},{"id":"p07","title":"易错字：逐字落实","content":"常见易错：沧（沧海）、粟（一粟）、钩（钩连）、砺（金就砺）、篇（篇章）、黔（黎民）、槁（槁暴）。写前先辨易错字，写后逐字核对。"},{"id":"p08","title":"答题规范：一字不差","content":"默写题按原文书写，不添字漏字、不用同音字。写完默读一遍，重点检查易错字与是否漏句。"}],"quiz":[{"id":"q09","stem":"《劝学》：青，取之于蓝，而青于蓝；＿＿＿＿＿，而寒于水。","options":["冰，水为之","水为之","冰水为之","水为之，而"],"answer":0,"analysis":"原文：冰，水为之，而寒于水。"},{"id":"q10","stem":"《师说》：师者，所以传道受业＿＿＿＿也。","options":["解惑","受惑","释惑","答疑"],"answer":0,"analysis":"原文“解惑”。"},{"id":"q11","stem":"《赤壁赋》：寄蜉蝣于天地，渺沧海之一＿＿＿＿。","options":["粟","栗","来","苏"],"answer":0,"analysis":"一粟：极言渺小。"},{"id":"q12","stem":"《念奴娇》：乱石穿空，惊涛拍岸，卷起千堆＿＿＿＿。","options":["雪","霜","云","浪"],"answer":0,"analysis":"千堆雪：形容浪花如雪。"},{"id":"q13","stem":"《琵琶行》：别有幽愁暗恨生，此时无声＿＿＿＿。","options":["胜有声","是有声","胜于声","更无声"],"answer":0,"analysis":"原文“此时无声胜有声”。"},{"id":"q14","stem":"《逍遥游》：且夫水之积也不厚，则其负大舟也＿＿＿＿。","options":["无力","无志","无勇","无德"],"answer":0,"analysis":"原文“无力”。"},{"id":"q15","stem":"下列词语中“粟”的写法，正确的一项是（　）","options":["沧海一粟","沧海一栗","沧海一粟（栗）","沧海一米"],"answer":0,"analysis":"一粟：粟＝小米，指渺小。"},{"id":"q16","stem":"默写题答题最关键的是（　）","options":["字迹工整","一字不差","写满格","加分号"],"answer":1,"analysis":"默写按原文，一字不差。"}]},{"id":"hl3","title":"文言文实词虚词与句式","grade_tag":"高考文言","summary":"文言文阅读以“读懂”为核心，重点突破实词一词多义、虚词用法、特殊句式与翻译准确。","points":[{"id":"p09","title":"实词：一词多义语境定","content":"“假”借（善假于物）／借道（假道伐虢）／借（假寐）；“道”道理（传道）／道路（道之所存）；“相”互相（教学相长）。抓语境、找语境义。"},{"id":"p10","title":"虚词：18 个高频虚词","content":"之（取消句子独立性／代词／到）、而（并列／承接／转折／修饰）、于（在／到／对／被／用）、其（代词／语气）、以（用／因／来）。虚词看位置定功能。"},{"id":"p11","title":"特殊句式：判断与还原","content":"判断句（A 是 B）、被动句（受／于／为……所）、宾语前置（惟……是）、状语后置（于＋名词）。还原时调语序、加标志。"},{"id":"p12","title":"翻译：直译为主","content":"翻译做到“字字落实、句句通顺、直译为主、删补为辅”。留指代词、调整语序、补出省略成分，忌随意改写。"}],"quiz":[{"id":"q17","stem":"“善假于物也”的“假”意思是（　）","options":["虚假","借助","借给","假设"],"answer":1,"analysis":"假：借助。"},{"id":"q18","stem":"“而智勇多困于所溺”的句式是（　）","options":["判断句","被动句","状语后置","宾语前置"],"answer":1,"analysis":"“困于所溺”即被所溺困住，被动句。"},{"id":"q19","stem":"下列含状语后置句的一项是（　）","options":["不吾知也","蚓无爪土之利","何陋之有","沛公先破关"],"answer":1,"analysis":"“蚓无爪土之利”即蚯蚓没有（用）爪和土的便利，状语后置。"},{"id":"q20","stem":"“教学相长”的“相”意思是（　）","options":["辅相","互相","宰相","相国"],"answer":1,"analysis":"相：互相。"},{"id":"q21","stem":"翻译“蚓无爪土之利”应译为（　）","options":["蚯蚓没有爪和土","蚯蚓没有（用）爪和土的便利","蚯蚓没有泥土","蚯蚓有爪和土的力"],"answer":1,"analysis":"“之”是定语标志，“利于土”的状语后置，译为“（用）爪和土的便利”。"},{"id":"q22","stem":"“道之所存”的“之”意思是（　）","options":["取消句子独立性","代词","到","的"],"answer":0,"analysis":"“之”在主谓之间，取消句子独立性，不译。"},{"id":"q23","stem":"翻译重点是落实每个字，尤其注意（　）","options":["加形容词","留指代、调语序","删主语","用意译"],"answer":1,"analysis":"翻译要留指代词、调整语序。"},{"id":"q24","stem":"下列“而”表转折的一项是（　）","options":["学而不厌","人不知而不愠","温故而知新","其知虽少"],"answer":1,"analysis":"B 转折。"}]},{"id":"hl4","title":"古诗词鉴赏与情感主旨","grade_tag":"高考鉴赏","summary":"鉴赏题要抓意象、意境、手法，答“情感＋手法＋效果”三要素，做到言之成理、术语规范。","points":[{"id":"p13","title":"常见意象与情感","content":"月亮——思乡怀人；杨柳——惜别；鸿雁——音信；松柏——坚贞；梧桐——愁苦。熟记意象对应的常见情感。"},{"id":"p14","title":"答题三要素","content":"①情感态度（思乡／怀人／励志／悲愤）；②表现手法（托物言志／借景抒情／直抒胸臆／对比／虚实）；③效果分析（生动、深刻、结构作用）。"},{"id":"p15","title":"炼字题：字＋义＋情","content":"炼字题格式：本字含义＋在句中含义＋表达效果＋情感。如“涛”写波涛汹涌，映衬出作者胸中块垒。"},{"id":"p16","title":"结构类：句法与情感作用","content":"开头：开门见山／点题；中间：承上启下／推进；结尾：总结／升华／卒章显志。答作用要结合内容与情感。"}],"quiz":[{"id":"q25","stem":"“举头望明月，低头思故乡”运用的手法是（　）","options":["比喻","借景抒情","夸张","排比"],"answer":1,"analysis":"借月抒发思乡之情，属借景抒情。"},{"id":"q26","stem":"“落木萧萧下，不尽长江滚滚来”描绘的画面是（　）","options":["春光明媚","苍茫辽阔的秋景","繁华都市","小桥流水"],"answer":1,"analysis":"落叶与长江勾勒出苍茫秋景。"},{"id":"q27","stem":"《赤壁赋》主旨是（　）","options":["积极乐观的人生态度","人生苦短及时行乐","怀才不遇","思念故乡"],"answer":0,"analysis":"作者最终超越生死，表现出旷达乐观。"},{"id":"q28","stem":"下列属于借物言志的一项是（　）","options":["蝉噪林逾静","月亮代表我的心","《橘颂》借橘喻坚贞","床前明月光"],"answer":2,"analysis":"《橘颂》借橘子“独立不迁”喻坚贞品格，属托物言志。"},{"id":"q29","stem":"鉴赏题答题的三个要素是（　）","options":["情感＋手法＋效果","时间＋地点＋人物","开头＋中间＋结尾","比喻＋拟人＋排比"],"answer":0,"analysis":"情感、手法、效果三要素。"},{"id":"q30","stem":"“夕阳无限好，只是近黄昏”蕴含的情感是（　）","options":["赞美自然","对美好事物消逝的惋惜","田园之乐","爱国之情"],"answer":1,"analysis":"蕴含对美好事物易逝的惋惜。"},{"id":"q31","stem":"“大漠孤烟直，长河落日圆”主要运用的修辞是（　）","options":["比喻","对偶","拟人","夸张"],"answer":1,"analysis":"对偶句式，描绘塞外风光。"},{"id":"q32","stem":"句子在结构中的作用不包括（　）","options":["开门见山","承上启下","卒章显志","借景抒情"],"answer":3,"analysis":"“借景抒情”是表现手法，非结构作用。"}]},{"id":"hl5","title":"现代文阅读·论述类文本","grade_tag":"高考阅读","summary":"论述类文本考查概念理解、论证分析、观点整合，要读懂每个选项与原文的对应关系。","points":[{"id":"p17","title":"题型：选择题为主","content":"常见题型：概念含义、行文脉络、论证方法、作者观点、比较探究。设错多为“偷换概念、以偏概全、无中生有、混淆时态”。"},{"id":"p18","title":"解题：回归原文比对","content":"每个选项都回原文找依据，划出关键词比对。含“都、全、唯一、必然、绝对”等词的选项往往错。"},{"id":"p19","title":"论证方法与作用","content":"举例论证（具体有力）、对比论证（突出差异）、道理论证（揭示本质）、比喻论证（生动形象）。答“方法＋作用”。"},{"id":"p20","title":"整合与推断","content":"推断题要基于原文，不能主观发挥。选项与原文有细微差异即为陷阱，注意时间、范围、程度。"}],"quiz":[{"id":"q33","stem":"论述类文本阅读主要考查（　）","options":["作者情感态度","概念理解与论证分析","故事情节","人物性格"],"answer":1,"analysis":"论述类聚焦概念、行文、论证。"},{"id":"q34","stem":"下列关于论述类文本说法正确的一项是（　）","options":["要多选主观题","设错多为无中生有等","不需回原文","只看选项"],"answer":1,"analysis":"设错多无中生有、以偏概全等。"},{"id":"q35","stem":"举例论证的作用是（　）","options":["揭示本质","具体有力，使论证真实可信","生动形象","突出差异"],"answer":1,"analysis":"举例论证使论证具体有力。"},{"id":"q36","stem":"含“都、全、唯一”的选项通常（　）","options":["正确","可能有误","必对","无关"],"answer":1,"analysis":"绝对化词语往往是错误信号。"},{"id":"q37","stem":"推断题应（　）","options":["基于原文推断","凭主观发挥","随意联想","跳过原文"],"answer":0,"analysis":"推断必须基于原文。"},{"id":"q38","stem":"行文脉络题关注（　）","options":["段落层次与逻辑","修辞","作者生平","标题含义"],"answer":0,"analysis":"脉络题关注结构层次。"},{"id":"q39","stem":"概念题的解题关键是（　）","options":["结合上下文限定","只看标题","凭经验","看选项"],"answer":0,"analysis":"概念题要抓上下文限定。"},{"id":"q40","stem":"比较探究题的答题重点是（　）","options":["结合材料，分点作答","综合两则材料","列举例子","语言优美"],"answer":0,"analysis":"比较探究要结合材料分点作答。"}]},{"id":"hl6","title":"现代文阅读·文学类与实用类","grade_tag":"高考阅读","summary":"文学类重形象与表达，实用类（非连续性文本）重信息筛选与比较，二者答题规范不同。","points":[{"id":"p21","title":"文学类题型","content":"人物形象（性格＋分析＋文中依据）、环境作用（渲染、烘托、推动）、表达效果（结合手法＋情感）、标题含义（表层＋深层）。"},{"id":"p22","title":"文学类答题格式","content":"答题要“手法＋内容＋情感”三点结合。如：以比喻手法，把××比作××，生动写出××的××，表达××之情。"},{"id":"p23","title":"实用类非连续性文本","content":"非连续性文本由多则材料组成，题型含选择题、概括题、比较题。关键在比对多则材料，找关联与差异。"},{"id":"p24","title":"实用类答题规范","content":"概括题答案要“分条、简洁、全面”，每条一个要点，尽量用材料原词。比较题要“先同后异／先异后同”。"}],"quiz":[{"id":"q41","stem":"小说人物形象题答题格式是（　）","options":["性格＋分析＋文中依据","时间＋地点","起因＋结果","外貌＋语言"],"answer":0,"analysis":"人物形象＝性格＋分析＋文中依据。"},{"id":"q42","stem":"环境描写的作用不包括（　）","options":["渲染气氛","烘托人物","推动情节","直接抒情"],"answer":3,"analysis":"直接抒情不是环境的作用。"},{"id":"q43","stem":"非连续性文本的组成特点是（　）","options":["多则材料，话题相关","单一材料","纯文学作品","无标题"],"answer":0,"analysis":"非连续性文本由多则相关材料组成。"},{"id":"q44","stem":"实用类概括题答案要求（　）","options":["分条、简洁、全面","一段话","文学化","有主语"],"answer":0,"analysis":"概括题要分条简洁全面。"},{"id":"q45","stem":"小说标题含义题的答法是（　）","options":["表层含义＋深层含义","字面意思","作者生平","写作背景"],"answer":0,"analysis":"标题含义从表层与深层两方面答。"},{"id":"q46","stem":"以下不属于文学类文本常见题型的是（　）","options":["人物形象分析","表达效果分析","非连续性信息筛选","标题含义解读"],"answer":2,"analysis":"信息筛选属实用类。"},{"id":"q47","stem":"非连续性文本比较题答法是（　）","options":["先同后异","只答异","只答同","综合概括"],"answer":0,"analysis":"比较题先同后异或先异后同。"},{"id":"q48","stem":"文学类表达效果题需结合（　）","options":["手法＋内容＋情感","字数","标题","作者名"],"answer":0,"analysis":"表达效果要结合手法、内容、情感。"}]},{"id":"hl7","title":"语言表达·补写、得体与连贯","grade_tag":"高考语言","summary":"语言表达类考补写句子、语言得体、语句连贯、图文转换，是高考语文的常考主观题。","points":[{"id":"p25","title":"补写句子：抓话题与逻辑","content":"补写要抓上下文话题一致、逻辑连贯（转折用“但”、递进用“更”）、句式一致。先读懂上下文再补。"},{"id":"p26","title":"语言得体：五看","content":"看对象（对谁说）、看身份、看场合、看目的、看称谓敬辞。得体＝说话人身份与语境的匹配。"},{"id":"p27","title":"语句连贯：排序与衔接","content":"排序题抓总起句（首句）、关联词、重复关键词。衔接题抓代词、关联词、同义词照应。"},{"id":"p28","title":"图文转换与压缩","content":"图表题要“横向比＋纵向比＋总体趋势”，注意单位与图例。语言简洁、完整、准确，不写多余分析。"}],"quiz":[{"id":"q49","stem":"补写句子应首先考虑（　）","options":["字数一致","话题一致、逻辑连贯","押韵","用词华丽"],"answer":1,"analysis":"话题一致、逻辑连贯是首要。"},{"id":"q50","stem":"下列表达最得体的一项是（　）","options":["您过来一下","请过来一下","请你务必过来","你快点过来"],"answer":1,"analysis":"“请过来一下”礼貌得体。"},{"id":"q51","stem":"排序题最重要的线索是（　）","options":["首句总起","字数","标点","段落数"],"answer":0,"analysis":"首句总起句是重要线索。"},{"id":"q52","stem":"表示转折关系的关联词是（　）","options":["但是","因此","而且","虽然"],"answer":0,"analysis":"“但是”表转折。"},{"id":"q53","stem":"语言得体要看（　）","options":["说话人身份与语境","字数多少","用词难度","句式长短"],"answer":0,"analysis":"得体看身份与语境。"},{"id":"q54","stem":"图表题的答案应（　）","options":["横向纵向比较＋趋势","只写数字","只写结论","大段分析"],"answer":0,"analysis":"图表题要横向纵向比较并点出趋势。"},{"id":"q55","stem":"补写句中“更”字表明句子之间是（　）","options":["并列","递进","转折","因果"],"answer":1,"analysis":"“更”表递进。"},{"id":"q56","stem":"以下属于得体用法的是（　）","options":["你死哪去了","请问您贵姓","滚开","喂"],"answer":1,"analysis":"“请问您贵姓”得体。"}]},{"id":"hl8","title":"高考作文·审题立意与结构","grade_tag":"高考作文","summary":"高考作文分审题（不偏题）、立意（高远有思辨）、结构（清晰有层次）、语言（准确有文采）四关。","points":[{"id":"p29","title":"审题：抓住关键词","content":"审题抓住材料核心词与限制语。如“钥匙”——思考工具与人的关系，而非只谈钥匙。审题不清则全盘皆输。"},{"id":"p30","title":"立意：思辨高远","content":"立意要“见别人所见、言别人所不言”。可从关系（人与工具）、态度（快与慢）、价值观（坚守与变通）入手，体现辩证思维。"},{"id":"p31","title":"结构：总—分—总","content":"常见结构：引论（亮观点）—本论（分 2-3 层论证）—结论（升华）。每层用小论点＋事例＋分析。"},{"id":"p32","title":"语言与卷面","content":"语言准确、简练、有表现力，善用比喻与排比。卷面整洁，标题醒目，800字左右。"}],"quiz":[{"id":"q57","stem":"作文审题首先应抓住（　）","options":["词句文采","关键词与限制语","开头","结尾"],"answer":1,"analysis":"审题抓关键词与限制语。"},{"id":"q58","stem":"立意高远体现的是（　）","options":["思辨性","字数多","名人多","开头亮"],"answer":0,"analysis":"立意高远即有思辨。"},{"id":"q59","stem":"结构“引—论—结”对应的是（　）","options":["总—分—总","并列","时间顺序","空间顺序"],"answer":0,"analysis":"引论结即总分总。"},{"id":"q60","stem":"议论文本论层每层应包含（　）","options":["小论点＋事例＋分析","只有事例","只有观点","描写"],"answer":0,"analysis":"每层要有小论点、事例、分析。"},{"id":"q61","stem":"“所有、必然”等绝对化表述在作文中的问题是（　）","options":["语气强","易失严谨","显文采","显激情"],"answer":1,"analysis":"绝对化表述易失严谨。"},{"id":"q62","stem":"作文标题最宜（　）","options":["含蓄醒目，切合材料","长难","照抄材料","越花哨越好"],"answer":0,"analysis":"标题要含蓄醒目、切合材料。"},{"id":"q63","stem":"记叙文要突出真情实感，靠（　）","options":["细节描写","议论","大道理","排比"],"answer":0,"analysis":"记叙文靠细节描写动情。"},{"id":"q64","stem":"作文立意“思辨”主要体现在（　）","options":["一分为二看问题","写满字数","用很多典故","开头精彩"],"answer":0,"analysis":"思辨即一分为二辩证看问题。"}]}]};
