// === PHYSICS_LINK_DEFAULT_START ===
var physics_link_default = {"units":[{"id":"pl1","title":"力学·受力分析与牛顿定律","grade_tag":"八年级至高一","summary":"梳理受力分析步骤与牛顿三定律，配套小测巩固受力判断与定律应用。","points":[{"h":"受力分析三步法","body":"确定研究对象→分析接触面内外各个力→判断施力物体（先重力后弹力摩擦力）。注意只画真实力，不画效果力与虚拟力。","eg":"例：斜面上的物体受重力、支持力、摩擦力三个力，不画「下滑力」。","tip":"💡 受力分析是力学解题的第一步，漏力或添力必错。"},{"h":"牛顿第一定律与惯性","body":"一切物体都有保持原有运动状态的性质（惯性）；外力为零时物体保持静止或匀速直线运动。","eg":"例：汽车突然刹车时乘客向前倾，是由于人有惯性。","tip":"💡 惯性是性质，只与质量有关，与速度无关。"},{"h":"牛顿第二定律 F合=ma","body":"加速度由合外力决定，与合外力成正比、与质量成反比，方向与合外力相同。单位制中 1 N = 1 kg·m/s²。","eg":"例：质量 2 kg 的物体受 6 N 合外力，加速度为 3 m/s²。","tip":"💡 牛顿第二定律是矢量式，要先选正方向再列式。"},{"h":"牛顿第三定律","body":"作用力与反作用力大小相等、方向相反、作用在两个不同物体上，同生共灭。","eg":"例：人推墙时，人推墙的力与墙推人的力等大反向。","tip":"💡 「等大反向」不等于「平衡」，平衡力作用在同一物体上。"}],"quiz":[{"id":"pl1q1","stem":"关于惯性，下列说法正确的是","options":["与速度有关","与质量有关","与受力有关","物体静止时没有惯性"],"answer":1,"analysis":"惯性是物体保持原有运动状态的性质，大小只与质量有关。"},{"id":"pl1q2","stem":"牛顿第二定律的表达式是","options":["F=mg","F合=ma","F=kx","F=μmg"],"answer":1,"analysis":"牛顿第二定律：合外力等于质量与加速度的乘积。"},{"id":"pl1q3","stem":"作用力与反作用力","options":["大小可以不相等","作用在同一物体上","一定是一对平衡力","等大反向且作用在不同物体上"],"answer":3,"analysis":"作用力与反作用力等大反向、作用于不同物体，不属于平衡力。"},{"id":"pl1q4","stem":"质量 4 kg 的物体在 10 N 合外力作用下，加速度为","options":["0.4 m/s²","2.5 m/s²","40 m/s²","4 m/s²"],"answer":1,"analysis":"a=F合/m=10/4=2.5 m/s²。"}]},{"id":"pl2","title":"运动学·匀变速与抛体圆周","grade_tag":"高一年级至高二","summary":"串联位移—速度—加速度关系与曲线运动，配套小测巩固公式选择与条件判断。","points":[{"h":"匀变速直线运动三大公式","body":"v=v₀+at；x=v₀t+½at²；v²-v₀²=2ax。选公式前先判断\"缺哪个量\"，含 t 用①②，含 v₀/v 关系用③。","eg":"例：求末速度用 v=v₀+at，求高度用 h=v₀t+½at²。","tip":"💡 三个公式各有适用条件，勿混用。"},{"h":"自由落体与竖直上抛","body":"自由落体：v₀=0、a=g，h=½gt²。竖直上抛上升时加速度仍为 g（向下），故最高点 v=0 但 a=g。","eg":"例：竖直上抛最高点速度为零、加速度为 g，不是静止。","tip":"💡 「速度为零」不等于「加速度为零」。"},{"h":"平抛与斜抛","body":"平抛分解为水平匀速与竖直自由落体；飞行时间只由高度决定，与水平初速度无关；射程 x=v₀√(2h/g)。","eg":"例：同样高度、不同初速的两个小球同时落地。","tip":"💡 平抛是「分运动等时性」的典型应用。"},{"h":"圆周运动与向心力","body":"v=ωr=2πr/T；F向=mv²/r=mω²r，指向圆心。向心力是按效果命名的力，可由重力、弹力、摩擦力等合成提供。","eg":"例：汽车转弯靠摩擦力提供向心力。","tip":"💡 向心力不是一种新性质的力，是效果力。"}],"quiz":[{"id":"pl2q1","stem":"自由落体运动的加速度大小约为","options":["9.8 m/s²","1 m/s²","10 N","与质量有关"],"answer":0,"analysis":"自由落体加速度 g≈9.8 m/s²，与质量无关。"},{"id":"pl2q2","stem":"平抛运动的飞行时间取决于","options":["初速度大小","抛出点高度","水平射程","初速度方向"],"answer":1,"analysis":"平抛时间只由竖直方向决定，即由高度决定。"},{"id":"pl2q3","stem":"向心力的方向","options":["沿运动方向","指向圆心","竖直向下","与速度垂直向外"],"answer":1,"analysis":"向心力始终指向圆心，即沿半径指向内。"},{"id":"pl2q4","stem":"竖直上抛物体到达最高点时","options":["加速度为零","速度为零","动能最大","重力势能最小"],"answer":1,"analysis":"最高点速度为零，但加速度仍为 g，动能最小、重力势能最大。"}]},{"id":"pl3","title":"功与能量·机械能守恒","grade_tag":"高一年级至高二","summary":"辨析功、功率、动能定理与机械能守恒条件，配套小测巩固条件判断。","points":[{"h":"功与功率","body":"W=Fs cosθ，功是过程量，描述做功多少，单位 J；P=W/t，功率是状态量，描述做功快慢，单位 W。","eg":"例：功率大表示做功快，不一定做功多。","tip":"💡 「多做功」与「做功快」是两件事。"},{"h":"动能定理","body":"合外力做的总功等于物体动能的变化：W合=ΔEk。它不关心过程只看初末状态，是解题利器。","eg":"例：无论用什么方法，只要合功相同，动能变化就相同。","tip":"💡 动能定理是「过程量—状态量」的桥梁。"},{"h":"机械能守恒条件","body":"只有重力或系统内弹力做功（其他力做功为零或转化为势能）时，机械能 E=Ek+Ep 守恒。","eg":"例：单摆在空气中摆动，因有空气阻力，机械能减小。","tip":"💡 有摩擦、空气阻力时机械能不守恒。"},{"h":"功能关系与能量守恒","body":"重力做功与重力势能变化互为相反数；弹力做功与弹性势能变化同理。能量守恒是最普遍规律。","eg":"例：物块下滑 h，动能增加 mgh。","tip":"💡 能量守恒适用范围远大于机械能守恒。"}],"quiz":[{"id":"pl3q1","stem":"关于功和功率，说法正确的是","options":["功率大做功一定多","功表示做功的快慢","功率表示做功快慢","功的单位是瓦特"],"answer":2,"analysis":"功率 P=W/t 表示做功快慢，功的单位是焦耳。"},{"id":"pl3q2","stem":"机械能守恒的条件是","options":["物体匀速运动","只有重力或弹力做功","物体静止","物体受恒力作用"],"answer":1,"analysis":"机械能守恒要求只有重力或系统内弹力做功。"},{"id":"pl3q3","stem":"动能定理的表达式是","options":["W=ΔEk","P=W/t","F=ma","Ep=mgh"],"answer":0,"analysis":"动能定理：合外力总功等于动能变化 W合=ΔEk。"},{"id":"pl3q4","stem":"关于重力势能，说法正确的是","options":["与质量无关","与高度无关","Ep=mgh，与质量和高度均有关","是矢量"],"answer":2,"analysis":"重力势能 Ep=mgh，与质量、高度均有关，Ep 是标量。"}]},{"id":"pl4","title":"电磁学·电场电路磁场","grade_tag":"高一年级至高二","summary":"梳理库仑定律、电场强度、电势、欧姆定律与磁场受力，配套小测巩固。","points":[{"h":"库仑定律与电场强度","body":"库仑定律 F=kQ₁Q₂/r²。电场强度 E=F/q 表示电场本身强弱，由场源电荷和距离决定，与试探电荷无关。","eg":"例：试探电荷换成原电荷的 2 倍，电场强度不变。","tip":"💡 E 是电场性质，与放入的电荷无关。"},{"h":"电势与电势差","body":"电场力做正功电势能减少。U=Ed（匀强电场）。电势是标量，沿电场线方向降低，由电场和零势点决定。","eg":"例：沿电场线由高势点走向低势点。","tip":"💡 顺着电场线，电势降低。"},{"h":"闭合电路欧姆定律","body":"部分电路 I=U/R；闭合电路 I=E/(R+r)，r 为电源内阻。电阻 R=ρl/S。","eg":"例：串联电路电流处处相等，总电压等于各部分之和。","tip":"💡 部分与闭合电路欧姆定律不要混用。"},{"h":"安培力与洛伦兹力","body":"安培力 F=BIL，洛伦兹力 F=qvB，方向均用左手定则判断。带电粒子在匀强磁场中做匀速圆周运动，r=mv/qB。","eg":"例：回旋加速器用洛伦兹力使粒子加速做圆周运动。","tip":"💡 左手定则：磁感线穿手心，四指电流，正拇指受力。"}],"quiz":[{"id":"pl4q1","stem":"电场强度 E 与试探电荷的关系是","options":["E 与 q 成正比","E 与 q 成反比","E 与 q 无关","E 随 q 增大而增大"],"answer":2,"analysis":"E=F/q 反映电场本身强弱，由场源决定，与试探电荷无关。"},{"id":"pl4q2","stem":"沿电场线方向电势","options":["升高","降低","不变","不能确定"],"answer":1,"analysis":"沿电场线方向电势逐渐降低。"},{"id":"pl4q3","stem":"判断安培力方向使用","options":["左手定则","右手定则","右手螺旋定则","不需要判断"],"answer":0,"analysis":"安培力与洛伦兹力方向均用左手定则判断。"},{"id":"pl4q4","stem":"闭合电路中电源内阻为 r，则电流 I=","options":["U/R","E/(R+r)","E/R","E·R/r"],"answer":1,"analysis":"闭合电路欧姆定律 I=E/(R+r)。"}]},{"id":"pl5","title":"实验与探究·物理方法","grade_tag":"八年级至高三","summary":"梳理初中高中常见物理实验与科学方法，配套小测巩固实验设计与误差分析。","points":[{"h":"控制变量法","body":"研究多个因素影响的规律时，只改变一个因素、保持其他不变。例：探究加速度与力质量关系时保持 m 不变改变 F。","eg":"例：探究滑动摩擦力与压力关系时改变压力而控制接触面不变。","tip":"💡 控制变量法是实验题的核心思路。"},{"h":"等效替代法","body":"用效果的等效量替代不便直接测量的量。例：用合力等效替代分力、用平均速度等效替代瞬时速度。","eg":"例：探究加速度时用「中间时刻速度」等效替代瞬时速度。","tip":"💡 等效替代常用于难以直接测量的物理量。"},{"h":"微小量放大法","body":"把微小变化放大成明显现象。例：微小形变用平面镜反射放大、光的微小位移用杠杆放大。","eg":"例：观察玻璃瓶微小形变时塞入带细管的水。","tip":"💡 放大法不改变被测量的性质，只改变观察难易。"},{"h":"理想模型与科学抽象","body":"把复杂对象理想化，抓住主要因素忽略次要因素。质点、点电荷、理想气体、理想变压器都是理想模型。","eg":"例：研究地球公转时把地球看作质点。","tip":"💡 建模是物理思维的起点，先问「简化了什么」。"}],"quiz":[{"id":"pl5q1","stem":"探究加速度与力的关系时采用的方法是","options":["控制变量法","等效替代法","放大法","类比法"],"answer":0,"analysis":"探究加速度与力、质量的关系采用控制变量法。"},{"id":"pl5q2","stem":"把物体看作质点采用的是","options":["控制变量法","理想模型法","等效替代法","实验推理法"],"answer":1,"analysis":"质点是理想模型法（科学抽象）的典型例子。"},{"id":"pl5q3","stem":"用平均速度等效替代瞬时速度属于","options":["控制变量法","等效替代法","放大法","转化法"],"answer":1,"analysis":"平均速度与该时刻瞬时速度数值相等的依据是等效替代。"},{"id":"pl5q4","stem":"下列属于放大法的是","options":["用天平测质量","用平面镜观察玻璃瓶微小形变","用秒表测时间","用刻度尺测长度"],"answer":1,"analysis":"用平面镜反射把微小形变放大，属微小量放大法。"}]}]};
