var history_exam_default = {"questions":[{"id":"hsc001","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":1,"stem":"我国历史上第一个王朝是","options":["夏朝","周朝","秦朝","商朝"],"answer":0,"analysis":"约公元前2070年禹建立夏朝，是我国历史上第一个王朝。"},{"id":"hsc002","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":1,"stem":"西周管理地方的主要制度是","options":["郡县制","分封制","行省制","科举制"],"answer":1,"analysis":"西周实行分封制，授予宗亲和功臣管理地方的权利。"},{"id":"hsc003","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":2,"stem":"目前已发现的我国最早的成熟文字是","options":["小篆","隶书","甲骨文","金文"],"answer":2,"analysis":"甲骨文是商周时期刻写在龟甲兽骨上的文字，是我国已发现最早的成熟文字。"},{"id":"hsc004","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":2,"stem":"\"战国七雄\"中不包括","options":["秦国","楚国","齐国","晋国"],"answer":3,"analysis":"战国七雄为齐楚秦燕赵魏韩，晋国已分裂为韩赵魏三家分晋。"},{"id":"hsc005","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":2,"stem":"秦朝统一使用的文字是","options":["小篆","隶书","甲骨文","金文"],"answer":0,"analysis":"秦朝以小篆为全国规范文字，统一使用。"},{"id":"hsc006","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":3,"stem":"秦朝为抵御匈奴修筑并连接原有屏障的是","options":["阿房宫","长城","大运河","丝绸之路"],"answer":1,"analysis":"秦朝连接原秦、赵、燕旧长城抵御匈奴，明长城在其基础上修筑。"},{"id":"hsc007","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":2,"stem":"西汉初期实行的统治政策是","options":["严刑峻法","闭关锁国","休养生息","穷兵黩武"],"answer":2,"analysis":"汉初吸取秦亡教训，推行休养生息，出现\"文景之治\"。"},{"id":"hsc008","grade":7,"topic":"中国古代史(七上)","type":"choice","difficulty":3,"stem":"汉武帝为加强思想统一采取的措施是","options":["无为而治","大跃进","焚书坑儒","罢黜百家、独尊儒术"],"answer":3,"analysis":"汉武帝接受董仲舒建议，罢黜百家、独尊儒术，确立儒家正统地位。"},{"id":"hsf001","grade":7,"topic":"中国古代史(七上)","type":"fill","difficulty":1,"stem":"秦朝统一后规定全国通行的货币是______钱。","answer":"圆形方孔半两","analysis":"秦朝以圆形方孔半两钱作为全国统一货币。"},{"id":"hsf002","grade":7,"topic":"中国古代史(七上)","type":"fill","difficulty":2,"stem":"西汉时为开辟通往西域的道路而派出的使者是______。","answer":"张骞","analysis":"汉武帝派张骞出使西域，为丝绸之路开辟奠定基础。"},{"id":"hsc009","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":2,"stem":"江南地区得到开发是在","options":["三国两晋南北朝时期","唐朝","宋朝","春秋时期"],"answer":0,"analysis":"三国两晋南北朝时期，北方人口大量南迁，江南地区得到开发。"},{"id":"hsc010","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":2,"stem":"正式确立科举制的朝代是","options":["汉朝","隋朝","唐朝","宋朝"],"answer":1,"analysis":"隋文帝初步建立通过考试选拔人才制度，隋炀帝设进士科标志正式确立。"},{"id":"hsc011","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":1,"stem":"唐太宗时期出现的盛世景象被称为","options":["康乾盛世","文景之治","贞观之治","开元盛世"],"answer":2,"analysis":"唐太宗时期政治清明、经济发展，史称\"贞观之治\"。"},{"id":"hsc012","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":2,"stem":"为中日文化交流作出重大贡献、六次东渡的是","options":["一行","晁衡","玄奘","鉴真"],"answer":3,"analysis":"鉴真和尚六次东渡日本，传播唐朝文化。"},{"id":"hsc013","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":3,"stem":"活字印刷术的发明者是","options":["毕昇","张衡","祖冲之","蔡伦"],"answer":0,"analysis":"北宋毕昇发明活字印刷术，比欧洲早约四百年。"},{"id":"hsc014","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":3,"stem":"明朝时期在北京修建的皇家宫殿是","options":["大运河","紫禁城","布达拉宫","兵马俑坑"],"answer":1,"analysis":"明成祖迁都北京，修建紫禁城为皇家宫殿；隋朝开凿大运河。"},{"id":"hsc015","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":3,"stem":"郑和下西洋最远到达","options":["欧洲","大洋洲","非洲东海岸和红海沿岸","美洲"],"answer":2,"analysis":"郑和船队最远到达非洲东海岸和红海沿岸。"},{"id":"hsc016","grade":7,"topic":"中国古代史(七下)","type":"choice","difficulty":2,"stem":"清朝设立军机处标志着","options":["内阁制度确立","丞相制度恢复","三权分立形成","君主专制达到顶峰"],"answer":3,"analysis":"军机处设置使君主专制进一步强化并达到顶峰。"},{"id":"hsf003","grade":7,"topic":"中国古代史(七下)","type":"fill","difficulty":2,"stem":"明朝科学家李时珍所著的药物学著作是______。","answer":"《本草纲目》","analysis":"李时珍著《本草纲目》，被誉为\"东方药物巨典\"。"},{"id":"hsf004","grade":7,"topic":"中国古代史(七下)","type":"fill","difficulty":2,"stem":"清朝前期人口增长较快，______政策起了重要作用。","answer":"摊丁入亩","analysis":"摊丁入亩废除人头税，隐匿人口现象减少，人口迅速增长。"},{"id":"hsc017","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":2,"stem":"雅典民主政治的最高权力机构是","options":["公民大会","陪审法庭","民众大会","元老院"],"answer":0,"analysis":"公民大会是雅典的最高权力机关，负责审议并决定一切国家大事。"},{"id":"hsc018","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":2,"stem":"《汉谟拉比法典》属于哪一文明古国的成果","options":["古印度","两河流域","古希腊","古埃及"],"answer":1,"analysis":"《汉谟拉比法典》是古巴比伦王国两河流域文明的成果。"},{"id":"hsc019","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":1,"stem":"提出\"日心说\"的科学家是","options":["牛顿","达尔文","哥白尼","伽利略"],"answer":2,"analysis":"哥白尼提出日心说，否定了教会\"地心说\"。"},{"id":"hsc020","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":2,"stem":"英国确立君主立宪制的标志性文件是","options":["《独立宣言》","1787年宪法","《大宪章》","《权利法案》"],"answer":3,"analysis":"1689年英国议会颁布《权利法案》，确立君主立宪制。"},{"id":"hsc021","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":3,"stem":"第一次工业革命的标志是","options":["蒸汽机的广泛使用","电力的广泛应用","内燃机的发明","珍妮机的发明"],"answer":0,"analysis":"瓦特改良蒸汽机并广泛应用，人类进入\"蒸汽时代\"。"},{"id":"hsc022","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":3,"stem":"第二次工业革命中电力广泛应用的标志是","options":["蒸汽机","发电机","内燃机","珍妮机"],"answer":1,"analysis":"发电机问世推动电力广泛应用，人类进入\"电气时代\"。"},{"id":"hsc023","grade":9,"topic":"世界古代史·近代史(九)","type":"choice","difficulty":3,"stem":"美国1787年宪法确立的原则是","options":["人民代表大会","君主立宪","三权分立与联邦制","议会共和"],"answer":2,"analysis":"1787年宪法确立联邦制、三权分立与制衡原则。"},{"id":"hsr001","grade":9,"topic":"世界古代史·近代史(九)","type":"read","difficulty":3,"title":"阅读材料，回答问题","passage":"材料：19世纪中期，英国已成为\"世界工厂\"，产品销往全球。与此同时，机器大生产取代手工劳动，城市人口急剧增长，工人阶级生活条件恶劣，贫富分化加剧。","questions":[{"stem":"材料反映的历史现象是","options":["英国仍以农业为主","工业革命推动英国成为世界工厂并引发社会问题","英国已完成资产阶级革命","英国开始殖民扩张"],"answer":1,"analysis":"材料既反映英国工业革命后成为世界工厂，也反映贫富分化等社会问题。"},{"stem":"针对材料反映的社会问题，马克思主义诞生的标志是","options":["《共产党宣言》发表","宪章运动","第一国际成立","巴黎公社"],"answer":0,"analysis":"1848年《共产党宣言》发表，标志着马克思主义诞生。"}]},{"id":"hsf005","grade":9,"topic":"世界古代史·近代史(九)","type":"fill","difficulty":2,"stem":"英国资产阶级革命爆发的标志性时间是______年。","answer":"1640","analysis":"1640年英国议会召开，标志资产阶级革命开始。"},{"id":"hsw001","grade":9,"topic":"世界古代史·近代史(九)","type":"write","difficulty":3,"stem":"请结合\"新航路开辟\"的影响，简述世界开始连成一个整体的意义。","answer":"参考要点：新航路开辟打破各洲相对隔绝状态，使世界开始连成一个整体；促进物种、商品、资本在全球流动，推动欧洲资本主义发展，也带来殖民掠夺与疾病传播等影响；商贸中心由地中海沿岸转移到大西洋沿岸。","analysis":"开放性作答，考查辩证评价能力，答案言之成理即可。"},{"id":"hsc024","grade":10,"topic":"中国近代史","type":"choice","difficulty":1,"stem":"中国近代史开端的标志是","options":["甲午战争","辛亥革命","虎门销烟","鸦片战争"],"answer":3,"analysis":"1840年鸦片战争爆发，中国开始沦为半殖民地半封建社会。"},{"id":"hsc025","grade":10,"topic":"中国近代史","type":"choice","difficulty":2,"stem":"洋务运动的口号是","options":["自强与求富","实业救国","扶清灭洋","民主与科学"],"answer":0,"analysis":"洋务运动前期以\"自强\"、后期以\"求富\"为口号。"},{"id":"hsc026","grade":10,"topic":"中国近代史","type":"choice","difficulty":2,"stem":"中国近代第一个全国规模的资产阶级政党是","options":["保国会","中国同盟会","兴中会","强学会"],"answer":1,"analysis":"1905年中国同盟会在日本东京成立，是近代第一个全国性资产阶级政党。"},{"id":"hsc027","grade":10,"topic":"中国近代史","type":"choice","difficulty":3,"stem":"新文化运动高举的两面大旗是","options":["自由与平等","改革与开放","民主与科学","实业与教育"],"answer":2,"analysis":"新文化运动高举\"民主\"（德先生）与\"科学\"（赛先生）两面大旗。"},{"id":"hsc028","grade":10,"topic":"中国近代史","type":"choice","difficulty":3,"stem":"五四运动成为新民主主义革命开端的主要依据是","options":["由无产阶级领导","发生在1919年","有学生参与","具有彻底反帝反封建性质"],"answer":3,"analysis":"五四运动是中国历史上彻底反帝反封建的爱国运动，是新民主主义革命开端。"},{"id":"hsc029","grade":10,"topic":"中国近代史","type":"choice","difficulty":3,"stem":"成为抗日战争时局转换枢纽的历史事件是","options":["西安事变","七七事变","皖南事变","九一八事变"],"answer":0,"analysis":"1936年西安事变和平解决，成为时局转换的枢纽。"},{"id":"hsc030","grade":10,"topic":"中国近代史","type":"choice","difficulty":3,"stem":"全民族抗战开始的标志是","options":["一二八事变","七七事变","八一三事变","九一八事变"],"answer":1,"analysis":"1937年七七事变（卢沟桥事变）标志全民族抗战开始。"},{"id":"hsc031","grade":10,"topic":"中国近代史","type":"choice","difficulty":2,"stem":"抗战期间中共提出的全面抗战路线，其总方针是","options":["战略相持","消极防御","持久战","速决战"],"answer":2,"analysis":"毛泽东《论持久战》提出持久战总方针与人民战争路线。"},{"id":"hsr002","grade":10,"topic":"中国近代史","type":"read","difficulty":3,"title":"阅读材料，回答问题","passage":"材料：自1840年以来，列强入侵使中国逐步沦为半殖民地半封建社会。为救亡图存，先进中国人进行了艰苦探索：学器物、学制度、学思想，并最终选择了革命道路。","questions":[{"stem":"材料中\"学器物\"阶段的历史事件是","options":["戊戌变法","洋务运动","辛亥革命","新文化运动"],"answer":1,"analysis":"学习西方器物技术对应洋务运动。"},{"stem":"材料中\"学制度\"阶段的代表性历史事件是","options":["洋务运动","戊戌变法与辛亥革命","新文化运动","义和团运动"],"answer":1,"analysis":"\"学制度\"对应戊戌变法（君主立宪）与辛亥革命（民主共和）。"},{"stem":"材料认为近代化探索的最终道路是","options":["改良道路","革命道路","技术道路","文化道路"],"answer":1,"analysis":"材料指出最终选择革命道路，即中国共产党领导的新民主主义革命。"}]},{"id":"hsf006","grade":10,"topic":"中国近代史","type":"fill","difficulty":2,"stem":"中国近代第一个不平等条约是《______条约》。","answer":"南京","analysis":"1842年清政府被迫签订《南京条约》，中国开始沦为半殖民地半封建社会。"},{"id":"hsf007","grade":10,"topic":"中国近代史","type":"fill","difficulty":3,"stem":"中国共产党第一次全国代表大会召开于______年。","answer":"1921","analysis":"1921年中共一大召开，宣告中国共产党成立。"},{"id":"hsw002","grade":10,"topic":"中国近代史","type":"write","difficulty":3,"stem":"有人说\"洋务运动是中国近代化的开端\"，也有人认为它失败了。请你评价这一运动。","answer":"参考要点：肯定其功绩——引进西方技术、创办近代工业，是中国近代化开端，客观上刺激了民族资本主义产生，对外国资本入侵起到一定抵制作用；指出局限——只学器物不变制度，甲午战败宣告破产，未能使中国富强。结论：是一次失败的封建统治者的自救运动，但开创了近代化先河。","analysis":"开放性作答，考查辩证评价历史事件的能力。"},{"id":"hsc032","grade":11,"topic":"中国现代史","type":"choice","difficulty":3,"stem":"揭开人民解放军战略进攻序幕的是","options":["辽沈战役","渡江战役","孟良崮战役","刘邓大军挺进大别山"],"answer":3,"analysis":"1947年刘邓大军千里跃进大别山，揭开战略进攻序幕。"},{"id":"hsc033","grade":11,"topic":"中国现代史","type":"choice","difficulty":2,"stem":"标志社会主义基本制度在中国确立的是","options":["三大改造基本完成","一五计划完成","十一届三中全会","开国大典"],"answer":0,"analysis":"1956年底三大改造基本完成，社会主义基本制度确立。"},{"id":"hsc034","grade":11,"topic":"中国现代史","type":"choice","difficulty":2,"stem":"我国第一部社会主义类型的宪法颁布于","options":["1949年","1954年","1982年","1956年"],"answer":1,"analysis":"1954年第一届全国人大制定《中华人民共和国宪法》。"},{"id":"hsc035","grade":11,"topic":"中国现代史","type":"choice","difficulty":3,"stem":"作出改革开放伟大决策的会议是","options":["中共十五大","中共八大","中共十一届三中全会","中共十四大"],"answer":2,"analysis":"1978年十一届三中全会作出改革开放决策。"},{"id":"hsc036","grade":11,"topic":"中国现代史","type":"choice","difficulty":3,"stem":"我国第一个经济特区不包括","options":["深圳","珠海","汕头","海南"],"answer":3,"analysis":"1980年设立深圳、珠海、汕头、厦门四个经济特区，海南1988年建省并设特区。"},{"id":"hsc037","grade":11,"topic":"中国现代史","type":"choice","difficulty":3,"stem":"提出建立社会主义市场经济体制目标的会议是","options":["中共十四大","中共十五大","中共十二大","中共十三大"],"answer":0,"analysis":"1992年中共十四大明确提出建立社会主义市场经济体制的目标。"},{"id":"hsc038","grade":11,"topic":"中国现代史","type":"choice","difficulty":2,"stem":"\"一五\"计划期间建成的重大工业成就不包括","options":["沈阳第一机床厂","上海宝钢","鞍钢","长春第一汽车制造厂"],"answer":1,"analysis":"上海宝钢是1978年后引进成套设备建成的现代化钢铁基地。"},{"id":"hsr003","grade":11,"topic":"中国现代史","type":"read","difficulty":3,"title":"阅读材料，回答问题","passage":"材料：1978年，中共十一届三中全会果断结束\"以阶级斗争为纲\"，把党和国家工作中心转移到经济建设上来，实行改革开放。此后中国经济持续高速增长，人民生活水平显著提高，综合国力大幅增强。","questions":[{"stem":"材料中工作中心转移的表述，说明十一届三中全会作出了什么决策","options":["改革开放","计划经济","优先发展重工业","恢复高考"],"answer":0,"analysis":"十一届三中全会作出把工作中心转移到经济建设、实行改革开放的决策。"},{"stem":"1992年中共十四大提出的经济体制改革目标是","options":["计划经济为主","建立社会主义市场经济体制","完全市场化","公有制为主体"],"answer":1,"analysis":"中共十四大明确建立社会主义市场经济体制的改革目标。"}]},{"id":"hsf008","grade":11,"topic":"中国现代史","type":"fill","difficulty":2,"stem":"1978年中共十一届三中全会后，党和国家工作中心转移到______上来。","answer":"经济建设","analysis":"十一届三中全会把党和国家工作中心转移到经济建设上来。"},{"id":"hsf009","grade":11,"topic":"中国现代史","type":"fill","difficulty":3,"stem":"中国于______年加入世界贸易组织。","answer":"2001","analysis":"2001年12月中国正式加入世界贸易组织，对外开放进入新阶段。"},{"id":"hsw003","grade":11,"topic":"中国现代史","type":"write","difficulty":3,"stem":"请以\"改革开放是一场伟大革命\"为题，谈谈你对改革开放历史意义的认识。","answer":"参考要点：①是决定当代中国命运的关键一招，极大解放和发展了社会生产力；②推动了中国特色社会主义从\"不够合格\"到\"完全合格\"的制度跃迁；③综合国力与人民生活水平显著提高；④形成全方位、多层次、宽领域的开放格局，为世界经济增长提供动力；⑤坚持改革开放是新时代必须坚持的一条根本国策。","analysis":"开放性作答，考查历史解释与家国情怀。"},{"id":"hsc039","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":2,"stem":"马克思主义诞生的标志是","options":["宪章运动","巴黎公社","《共产党宣言》发表","欧文主义运动"],"answer":2,"analysis":"1848年《共产党宣言》发表，标志着马克思主义诞生。"},{"id":"hsc040","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":3,"stem":"资本主义世界殖民体系最终形成的标志是","options":["凡尔赛体系建立","新航路开辟","世界市场形成","20世纪初资本主义世界殖民体系最终形成"],"answer":3,"analysis":"到20世纪初，资本主义世界殖民体系最终形成。"},{"id":"hsc041","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":3,"stem":"美苏冷战开始的标志是","options":["杜鲁门主义出台","北约成立","柏林墙修建","马歇尔计划"],"answer":0,"analysis":"1947年杜鲁门主义出台标志美苏冷战开始。"},{"id":"hsc042","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":3,"stem":"被称为\"经济联合国\"的世界组织是","options":["国际货币基金组织","世界贸易组织","联合国","世界银行"],"answer":1,"analysis":"世界贸易组织被称为\"经济联合国\"。"},{"id":"hsc043","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":3,"stem":"苏联解体后世界格局发展的趋势是","options":["单极格局确立","两极格局继续","多极化趋势加强","回到冷战"],"answer":2,"analysis":"苏联解体后两极格局结束，世界多极化趋势加强。"},{"id":"hsc044","grade":12,"topic":"世界近代史·现代史","type":"choice","difficulty":2,"stem":"推动欧洲走向联合的关键事件是","options":["北约成立","马歇尔计划","巴黎和会","欧共体成立"],"answer":3,"analysis":"1967年欧共体成立，推动欧洲一体化与联合。"},{"id":"hsr004","grade":12,"topic":"世界近代史·现代史","type":"read","difficulty":3,"title":"阅读材料，回答问题","passage":"材料：二战后，西欧国家在美国援助下逐步走向联合，1967年成立欧洲共同体；1993年欧洲联盟成立。欧洲一体化从经济领域起步并逐步扩展到政治、外交与安全领域。","questions":[{"stem":"材料中欧洲联合起步的领域是","options":["政治一体化","安全一体化","经济一体化","军事一体化"],"answer":2,"analysis":"欧洲共同体从经济领域联合起步，逐步扩展。"},{"stem":"材料体现欧洲一体化进程的特点是","options":["一步到位","由经济到政治多领域逐步扩展","完全由美国主导","仅限贸易往来"],"answer":1,"analysis":"欧洲一体化由经济联合起步，逐步扩展至政治外交等领域。"}]},{"id":"hsf010","grade":12,"topic":"世界近代史·现代史","type":"fill","difficulty":3,"stem":"被称为\"经济联合国\"的世界贸易组织，其前身是______。","answer":"关贸总协定","analysis":"世界贸易组织的前身是关税与贸易总协定（关贸总协定），1995年世贸组织成立。"},{"id":"hsw004","grade":12,"topic":"世界近代史·现代史","type":"write","difficulty":3,"stem":"请评述第二次工业革命对世界历史进程的影响。","answer":"参考要点：①推动生产力飞跃，人类进入\"电气时代\"；②促使垄断组织产生，主要资本主义国家进入垄断阶段；③改变世界经济格局，世界市场最终形成；④促进交通运输新发展（汽车、飞机等），推动城市化；⑤促使世界面貌发生深刻变化，同时带来环境污染等问题。","analysis":"开放性作答，考查历史影响评价能力。"}],"topics":["中国古代史(七上)","中国古代史(七下)","世界古代史·近代史(九)","中国近代史","中国现代史","世界近代史·现代史"]};
