// === HISTORY_DEFAULT_START ===
var history_default = {"sections":{"knowledge":{"groups":[{"id":"h7","title":"七年级·中国古代史（上）","grade_tag":"初一","items":[{"id":"h7a","term":"中华文明的起源与早期国家","jieshi":"我国境内在距今约五千年的黄河流域、长江流域出现文明曙光。炎帝黄帝部落是距今约四五千年部落联盟南方的传说，尧舜禹时期部落联盟首领由推举产生，\"禅让\"。约公元前2070年禹建立夏朝是我国历史上第一个王朝。","kao":{"q":"我国历史上第一个王朝是","options":["商朝","夏朝","周朝","秦朝"],"answer":1}},{"id":"h7b","term":"商周时期：青铜文明与分封制","jieshi":"商朝以青铜器制造水平高著称，代表器物有司母戊鼎、四羊方尊。约公元前1046年周武王灭商，西周建立。为稳定统治，周王根据血缘关系远近和功劳大小，将宗亲和功臣分封到各地，建立分封制。","kao":{"q":"西周管理地方的主要制度是","options":["郡县制","分封制","行省制","科举制"],"answer":1}},{"id":"h7c","term":"春秋争霸与战国七雄","jieshi":"春秋时期周王室衰微，诸侯争霸。战国时期兼并战争激烈，形成齐楚秦燕赵魏韩\"战国七雄\"。各诸侯国纷纷变法，封建制度逐步确立。","kao":{"q":"\"战国七雄\"中不包括","options":["秦国","楚国","齐国","晋国"],"answer":3}},{"id":"h7d","term":"秦统一多民族国家的建立","jieshi":"公元前221年秦王嬴政统一六国，建立我国历史上第一个统一的多民族的封建国家——秦朝。秦朝统一文字为小篆、货币为圆形方孔半两钱，规定全国使用度量衡，修筑长城。","kao":{"q":"秦朝统一使用的文字是","options":["甲骨文","金文","小篆","隶书"],"answer":2}},{"id":"h7e","term":"汉代的统一与治世","jieshi":"西汉初期推行休养生息政策，出现\"文景之治\"。汉武帝时采纳主父偃\"推恩\"建议颁布推恩令，削弱诸侯国势力；罢黜百家、独尊儒术，确立儒家思想的正统地位；北击匈奴，派张骞出使西域，开辟丝绸之路。","kao":{"q":"汉武帝为加强思想统一采取的措施是","options":["焚书坑儒","罢黜百家、独尊儒术","无为而治","大跃进"],"answer":1}}]},{"id":"h8","title":"七年级·中国古代史（下）","grade_tag":"初一","items":[{"id":"h8a","term":"魏晋南北朝：政权更迭与民族交融","jieshi":"东汉末年出现军阀混战，三国鼎立。220年曹丕建立魏国，266年司马炎建立西晋。此后北方经历十六国时期，南方经历东晋、宋、齐、梁、陈五个朝代。三国两晋南北朝时期江南地区得到开发，民族交融进一步加强。","kao":{"q":"江南地区得到开发是在","options":["春秋时期","三国两晋南北朝时期","唐朝","宋朝"],"answer":1}},{"id":"h8b","term":"隋唐一统：制度创新与对外交往","jieshi":"581年隋文帝建立隋朝，589年灭陈统一全国。隋朝创立科举制，正式确立于隋朝。618年李渊建立唐朝。唐太宗推行开明民族政策，轻徭薄赋，出现\"贞观之治\"。唐玄宗前期出现\"开元盛世\"，后期安史之乱使唐朝由盛转衰。唐朝实行开放的对外政策，遣唐使、玄奘西行、鉴真东渡。","kao":{"q":"正式确立科举制的朝代是","options":["汉朝","隋朝","唐朝","宋朝"],"answer":1}},{"id":"h8c","term":"辽宋夏金：多民族政权并立","jieshi":"916年契丹族建立辽，1038年党项族建立西夏，1115年女真族建立金，1127年金灭北宋。北宋时毕昇发明活字印刷术；司马光编《资治通鉴》；沈括著《梦溪笔谈》。南宋时朱熹编著《四书章句集注》，理学形成。","kao":{"q":"活字印刷术的发明者是","options":["蔡伦","毕昇","张衡","祖冲之"],"answer":1}},{"id":"h8d","term":"元明清：走向统一的多民族国家","jieshi":"1271年忽必烈建立元朝，结束长期分裂局面。明朝郑和七下西洋，航海规模空前。清朝设立军机处，标志君主专制达到顶峰。明朝李时珍著《本草纲目》，张居正推行一条鞭法。","kao":{"q":"标志着我国封建君主专制达到顶峰的是","options":["设立内阁","设军机处","设枢密院","设御史台"],"answer":1}}]},{"id":"h9","title":"九年级·世界古代史与近代史","grade_tag":"初三","items":[{"id":"h9a","term":"古代亚非文明与古典文明","jieshi":"两河流域的《汉谟拉比法典》是迄今已知世界上第一部较为完整的成文法典。古代埃及的金字塔与太阳神崇拜。古代印度的种姓制度和佛教的创立。希腊城邦的民主政治以雅典最具代表性，公民大会是最高权力机构。罗马共和国与罗马帝国的建立，十二铜表法标志成文法诞生。","kao":{"q":"雅典民主政治的最高权力机构是","options":["元老院","公民大会","陪审法庭","民众大会"],"answer":1}},{"id":"h9b","term":"文艺复兴与近代科学的兴起","jieshi":"14-16世纪意大利兴起文艺复兴，代表人物但丁、达·芬奇、莎士比亚。哥白尼提出日心说，伽利略创立自由落体定律，牛顿建立经典力学体系。新航路开辟使世界开始连成一个整体，物种交流与商业革命随之发生。","kao":{"q":"提出\"日心说\"的科学家是","options":["哥白尼","伽利略","牛顿","达尔文"],"answer":0}},{"id":"h9c","term":"英国资产阶级革命与美国独立战争","jieshi":"1640年英国议会召开，标志资产阶级革命开始。1689年《权利法案》颁布，确立君主立宪制，是资本主义代议制的确立。1775年美国独立战争爆发，1787年制定联邦宪法，确立三权分立与总统共和制。","kao":{"q":"英国确立君主立宪制的标志性文件是","options":["《大宪章》","《权利法案》","《独立宣言》","1787年宪法"],"answer":1}},{"id":"h9d","term":"法国大革命与工业革命","jieshi":"1789年法国大革命爆发，制宪议会颁布《人权宣言》。拿破仑战争打击欧洲封建势力。18世纪60年代英国开始工业革命，以蒸汽机的广泛使用为标志，人类进入\"蒸汽时代\"；19世纪中期扩展到法国、美国等。","kao":{"q":"第一次工业革命的标志是","options":["珍妮机的发明","蒸汽机的广泛使用","电力的广泛应用","内燃机的发明"],"answer":1}}]},{"id":"h10","title":"高中·中国近代史","grade_tag":"高一","items":[{"id":"h10a","term":"列强侵略与近代化的开端","jieshi":"鸦片战争后签订《南京条约》，中国开始沦为半殖民地半封建社会。洋务运动以\"自强\"\"求富\"为口号，创办近代军事与民用工业，是中国近代化的开端。早期维新思想主张君主立宪。","kao":{"q":"中国近代史开端的标志是","options":["虎门销烟","鸦片战争","甲午战争","辛亥革命"],"answer":1}},{"id":"h10b","term":"戊戌维新与辛亥革命","jieshi":"公车上书揭开维新变法运动序幕，维新派主张君主立宪，戊戌变法仅持续百余日。1905年中国同盟会成立，以\"驱除鞑虏，恢复中华，创立民国，平均地权\"为纲领。1911年武昌起义，1912年中华民国临时政府成立，宣告君主专制制度终结。","kao":{"q":"中国近代第一个全国规模的资产阶级政党是","options":["强学会","保国会","中国同盟会","兴中会"],"answer":2}},{"id":"h10c","term":"新文化运动与五四运动","jieshi":"1915年陈独秀创办《青年杂志》，新文化运动兴起，高举\"民主\"与\"科学\"两面大旗。1919年巴黎和会中国外交失败引发五四运动，是彻底反帝反封建的爱国运动，标志中国新民主主义革命的开端。","kao":{"q":"五四运动是新民主主义革命的开端，主要因为它","options":["具有彻底反帝反封建性质","由无产阶级领导","发生在1919年","有学生参加"],"answer":0}},{"id":"h10d","term":"国共十年对峙与抗日战争","jieshi":"1927年南昌起义打响武装反抗国民党反动派第一枪。1936年西安事变和平解决，成为时局转换的枢纽。1937年七七事变后全民族抗战开始，1945年抗日战争胜利。抗战期间中共提出全面抗战路线与持久战思想，开辟敌后战场，召开中共七届二中全会。","kao":{"q":"成为抗日战争时局转换枢纽的历史事件是","options":["九一八事变","西安事变","七七事变","皖南事变"],"answer":1}}]},{"id":"h11","title":"高中·中国现代史","grade_tag":"高二","items":[{"id":"h11a","term":"解放战争与新中国成立","jieshi":"1946年全面内战爆发。1947年刘邓大军挺进大别山揭开战略进攻序幕。1949年中华人民共和国成立，标志新民主主义革命取得基本胜利，中国人民从此站起来了。","kao":{"q":"揭开人民解放军战略进攻序幕的是","options":["孟良崮战役","刘邓大军挺进大别山","辽沈战役","渡江战役"],"answer":1}},{"id":"h11b","term":"社会主义革命与建设探索","jieshi":"1953年提出过渡时期总路线，1956年底三大改造基本完成，社会主义基本制度确立。1954年第一届全国人大召开，制定《中华人民共和国宪法》。全面建设社会主义时期取得大庆油田、两弹一星等成就，也出现大跃进和人民公社化运动的失误。","kao":{"q":"标志社会主义基本制度在中国确立的是","options":["开国大典","三大改造基本完成","一五计划完成","十一届三中全会"],"answer":1}},{"id":"h11c","term":"改革开放与现代化建设","jieshi":"1978年中共十一届三中全会作出把党和国家工作中心转移到经济建设上来、实行改革开放的决策。1980年设立深圳等经济特区，1992年中共十四大提出建立社会主义市场经济体制目标。2001年中国加入世界贸易组织。","kao":{"q":"作出改革开放伟大决策的会议是","options":["中共八大","中共十一届三中全会","中共十四大","中共十五大"],"answer":1}},{"id":"h11d","term":"新时代中国特色社会主义","jieshi":"党的十八大以来，中国特色社会主义进入新时代。中国共产党成立100周年、全面建成小康社会、脱贫攻坚战全面胜利。推动构建人类命运共同体，\"一带一路\"倡议提出并落地。","kao":{"q":"新时代我国对外开放的重要举措是","options":["加入世贸组织","共建\"一带一路\"","设立经济特区","浦东开发开放"],"answer":1}}]},{"id":"h12","title":"高中·世界近代史与现代史","grade_tag":"高三","items":[{"id":"h12a","term":"欧美主要国家的社会转型","jieshi":"17-18世纪欧美通过资产阶级革命确立资本主义制度：英国君主立宪制、美国总统共和制、法国议会共和制。工业革命推动城市化，19世纪中期英国成为世界工厂，马克思主义诞生。","kao":{"q":"马克思主义诞生的标志是","options":["《共产党宣言》发表","欧文主义运动","宪章运动","巴黎公社"],"answer":0}},{"id":"h12b","term":"垄断资本主义与殖民地体系","jieshi":"19世纪末20世纪初第二次工业革命兴起，主要国家进入垄断阶段，资本主义世界市场与殖民体系最终形成。列宁领导十月革命建立第一个社会主义国家。","kao":{"q":"资本主义世界殖民体系最终形成的标志是","options":["新航路开辟","世界市场形成","20世纪初资本主义世界殖民体系最终形成","凡尔赛体系建立"],"answer":2}},{"id":"h12c","term":"两次世界大战与现代国际秩序","jieshi":"一战后形成凡尔赛—华盛顿体系。二战后形成美苏两极格局，1947年杜鲁门主义标志冷战开始。1991年苏联解体，两极格局结束，世界多极化趋势加强。联合国成立于1945年。","kao":{"q":"美苏冷战开始的标志是","options":["马歇尔计划","杜鲁门主义出台","北约成立","柏林墙修建"],"answer":1}},{"id":"h12d","term":"经济全球化与人类社会","jieshi":"20世纪90年代以来经济全球化加速，世界贸易组织、世界银行、国际货币基金组织构成世界经济三大支柱。和平与发展成为时代主题。中国提出构建人类命运共同体理念。","kao":{"q":"被称为\"经济联合国\"的世界组织是","options":["世界银行","国际货币基金组织","世界贸易组织","联合国"],"answer":2}}]}]}}};
