// === POLITICS_DEFAULT_START ===
var politics_default = {"sections":{"knowledge":{"groups":[{"id":"p7","title":"七年级·成长的节拍与友谊","grade_tag":"初一","items":[{"id":"p7a","term":"中学时代的意义","jieshi":"中学时代是人生发展的一个新阶段，见证着一个人从少年到青年的生命进阶；它为我们的一生奠定重要基础，也为我们提供了发展自我的多种机会。","kao":{"q":"下列关于中学时代的认识，正确的是？","options":["中学时代可有可无","中学时代为一生奠定重要基础","中学时代只影响学习","中学时代越长越好"],"answer":1}},{"id":"p7b","term":"友谊的特质","jieshi":"友谊是一种亲密的关系，是平等的、双向的，也是一种心灵的相遇；友谊不是一成不变的，竞争并不必然伤害友谊，友谊不能没有原则。","kao":{"q":"真正的友谊应当具有的特质是？","options":["单方面付出","平等双向、心灵相遇","不讲原则包庇","永不改变"],"answer":1}},{"id":"p7c","term":"师生交往","jieshi":"老师是我们知识学习的指导者和精神成长的引路人；彼此尊重是师生交往的良好起点，我们要学会接纳不同风格的老师，亦师亦友。","kao":{"q":"与老师交往的良好起点是？","options":["成绩优秀","彼此尊重","顺从老师","少打交道"],"answer":1}},{"id":"p7d","term":"生命的价值","jieshi":"生命是宝贵的、不可逆的、短暂的；我们既要珍爱自己的生命，也要敬畏他人生命；生命的价值在于为国家、为社会、为他人作出贡献。","kao":{"q":"生命的价值主要在于？","options":["寿命长短","为国家社会他人作贡献","财富多少","名气大小"],"answer":1}},{"id":"p7e","term":"青春的邀约","jieshi":"青春期生理和心理都会发生变化；我们要悦纳生理变化，化解青春期矛盾心理，学会独立思考、培养批判精神、开发创造潜力。","kao":{"q":"面对青春期生理变化，正确态度是？","options":["焦虑不安","悦纳自我","盲目比较","刻意遮掩"],"answer":1}},{"id":"p7f","term":"情绪与情感","jieshi":"情绪是短暂、不稳定的，情感则相对持久；我们要学会调节情绪（转移注意、合理宣泄等），在品味情感中成长，传递情感正能量。","kao":{"q":"调节不良情绪的方法之一是？","options":["闷在心里","合理宣泄","迁怒他人","一味忍耐"],"answer":1}}]},{"id":"p8","title":"八年级·社会与法治","grade_tag":"初二","items":[{"id":"p8a","term":"社会生活离不开规则","jieshi":"社会规则明确社会秩序的内容、保障社会秩序的实现；自由与规则不可分，社会规则划定了自由的边界，也是人们享有自由的保障。","kao":{"q":"规则与自由的关系是？","options":["规则限制自由","规则划定自由边界并保障自由","自由不需要规则","规则越多越不自由"],"answer":1}},{"id":"p8b","term":"法律的特征与作用","jieshi":"法律由国家制定或认可、由国家强制力保证实施（最主要特征）、对全体社会成员具有普遍约束力；法律规范着全体社会成员的行为，保护我们的生活。","kao":{"q":"法律最主要的特征是？","options":["人人遵守","国家强制力保证实施","道德倡导","自愿履行"],"answer":1}},{"id":"p8c","term":"违法行为与犯罪","jieshi":"违法行为分为民事、行政、刑事三类；犯罪是具有严重社会危害性、刑事违法性、应受刑罚处罚的行为；我们要认清危害，远离违法犯罪。","kao":{"q":"犯罪的三个基本特征不包括？","options":["严重社会危害性","刑事违法性","应受刑罚处罚","轻微违法性"],"answer":3}},{"id":"p8d","term":"宪法是根本法","jieshi":"宪法是国家的根本法，是一切组织和个人的根本活动准则；具有最高的法律地位、法律权威和法律效力；宪法的核心价值追求是规范国家权力运行以保障公民权利。","kao":{"q":"宪法在国家法律体系中地位是？","options":["普通法律之一","根本法、效力最高","可有可无","只约束公民"],"answer":1}},{"id":"p8e","term":"公民基本权利","jieshi":"公民基本权利包括政治权利和自由、人身自由、社会经济与文化教育权利等；权利行使有界限，不得损害国家、社会、集体和他人的合法利益。","kao":{"q":"公民行使权利时应当？","options":["不受任何限制","以损害他人为代价","在法律界限内行使","只讲权利不尽义务"],"answer":2}},{"id":"p8f","term":"公民基本义务","jieshi":"公民必须履行遵守宪法法律、维护国家利益、依法服兵役、依法纳税等基本义务；权利与义务相统一，既要增强权利意识也要增强义务观念。","kao":{"q":"权利与义务的关系是？","options":["完全对立","相统一、不可分割","只尽义务不享权利","只享权利不尽义务"],"answer":1}}]},{"id":"p9","title":"九年级·国情与责任","grade_tag":"初三","items":[{"id":"p9a","term":"改革开放","jieshi":"改革开放是决定当代中国命运的关键抉择，是强国之路；极大解放和发展了社会生产力，使中国人民过上了幸福生活，是中国和世界共同发展进步的伟大历程。","kao":{"q":"对改革开放的认识，正确的是？","options":["可有可无","强国之路、关键抉择","导致贫穷","只影响城市"],"answer":1}},{"id":"p9b","term":"共同富裕","jieshi":"共同富裕是中国特色社会主义的本质要求，不是同步富裕、同等富裕；要让全体人民共享发展成果，朝着共同富裕方向稳步前进。","kao":{"q":"共同富裕是指？","options":["同步同时富裕","全体人民共享成果、逐步共富","部分人独富","平均主义"],"answer":1}},{"id":"p9c","term":"人民当家作主","jieshi":"我国是人民民主专政的社会主义国家，国家的一切权力属于人民；人民代表大会制度是我国的根本政治制度，是人民掌握国家政权、行使权力的根本途径。","kao":{"q":"我国的根本政治制度是？","options":["政治协商制度","人民代表大会制度","基层群众自治","民族区域自治"],"answer":1}},{"id":"p9d","term":"法治中国","jieshi":"依法治国是党领导人民治理国家的基本方略；全面依法治国是中国特色社会主义的本质要求和重要保障；法治要求实行良法之治和善治。","kao":{"q":"党领导人民治理国家的基本方略是？","options":["以德治国","依法治国","人治","无为而治"],"answer":1}},{"id":"p9e","term":"中华文化与民族精神","jieshi":"中华文化积淀着中华民族最深层的精神追求；民族精神以爱国主义为核心，包含团结统一、爱好和平、勤劳勇敢、自强不息。","kao":{"q":"中华民族精神的核心是？","options":["爱好和平","爱国主义","自强不息","勤劳勇敢"],"answer":1}},{"id":"p9f","term":"生态文明与绿色发展","jieshi":"人与自然相互依存、共生共荣；要坚持节约资源和保护环境的基本国策，走绿色发展道路，建设生态文明就是造福人类。","kao":{"q":"走绿色发展道路要求？","options":["先污染后治理","人与自然和谐共生","过度开发","放弃发展"],"answer":1}},{"id":"p9g","term":"中国梦","jieshi":"实现中华民族伟大复兴是近代以来中华民族最伟大的梦想；其基本内涵是国家富强、民族振兴、人民幸福；实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量。","kao":{"q":"中国梦的基本内涵是？","options":["个人发财","国家富强、民族振兴、人民幸福","称霸世界","照搬西方"],"answer":1}}]},{"id":"p10","title":"高一·中国特色社会主义","grade_tag":"高一","items":[{"id":"p10a","term":"原始社会","jieshi":"原始社会是人类社会发展的最初阶段；生产力低下，人们共同劳动、平均分配，没有私有制、阶级和国家；氏族是原始人共同生活的基本单位。","kao":{"q":"原始社会的分配方式是？","options":["按资分配","平均分配","按贡献分配","贫富分化"],"answer":1}},{"id":"p10b","term":"奴隶社会","jieshi":"奴隶社会代替原始社会是历史的进步；金属工具的广泛使用、文字的发明和应用等使人类摆脱蒙昧野蛮；奴隶主占有生产资料并完全占有奴隶。","kao":{"q":"奴隶社会代替原始社会是？","options":["历史倒退","历史的进步","无变化","偶然事件"],"answer":1}},{"id":"p10c","term":"封建社会与资本主义","jieshi":"地主阶级通过地租剥削农民；资本主义剥削的秘密是资本家无偿占有工人创造的剩余价值；资本主义基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾。","kao":{"q":"资本主义剥削的秘密是？","options":["延长工时","无偿占有剩余价值","提高工资","减少工人"],"answer":1}},{"id":"p10d","term":"科学社会主义","jieshi":"唯物史观和剩余价值学说奠定了科学社会主义的理论基石；《共产党宣言》的发表标志着科学社会主义的诞生；社会主义从空想变为科学。","kao":{"q":"科学社会主义诞生的标志是？","options":["巴黎公社","《共产党宣言》发表","十月革命","空想社会主义"],"answer":1}},{"id":"p10e","term":"中国特色社会主义创立","jieshi":"改革开放以来，中国共产党带领人民开创了中国特色社会主义道路；中国特色社会主义是根植于中国大地、反映人民意愿的科学社会主义。","kao":{"q":"中国特色社会主义道路是？","options":["照搬苏联","根植中国大地的科学社会主义","脱离实际","西方模式"],"answer":1}},{"id":"p10f","term":"中国梦","jieshi":"中国梦是国家的梦、民族的梦，也是每个中国人的梦；实现伟大梦想必须进行伟大斗争、建设伟大工程、推进伟大事业（四个伟大）。","kao":{"q":"实现中国梦的“四个伟大”不包括？","options":["伟大斗争","伟大工程","伟大事业","伟大个人"],"answer":3}}]},{"id":"p11","title":"高二·经济与社会·政治与法治","grade_tag":"高二","items":[{"id":"p11a","term":"我国基本经济制度","jieshi":"我国坚持公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度。","kao":{"q":"我国社会主义基本经济制度不包括？","options":["公有制为主体多种所有制共同发展","按劳分配为主体多种分配并存","社会主义市场经济体制","私有制为主体"],"answer":3}},{"id":"p11b","term":"市场经济与宏观调控","jieshi":"市场在资源配置中起决定性作用；科学的宏观调控是政府的主要职责和作用之一；要把有效市场与有为政府更好结合起来。","kao":{"q":"在资源配置中起决定性作用的是？","options":["政府计划","市场","行业协会","国际组织"],"answer":1}},{"id":"p11c","term":"收入分配与社会保障","jieshi":"收入分配要兼顾效率与公平，促进共同富裕；社会保障通过国民收入再分配，保障公民基本生活权利，维护社会公平稳定。","kao":{"q":"社会保障的主要作用是？","options":["拉大差距","保障基本生活、维护公平","减少税收","鼓励投机"],"answer":1}},{"id":"p11d","term":"中国共产党的领导","jieshi":"中国共产党是中国特色社会主义事业的领导核心；中国共产党的领导是中国特色社会主义最本质的特征，是中国特色社会主义制度的最大优势。","kao":{"q":"中国特色社会主义最本质的特征是？","options":["市场经济","中国共产党的领导","改革开放","共同富裕"],"answer":1}},{"id":"p11e","term":"人民当家作主制度体系","jieshi":"人民代表大会制度是根本政治制度；中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是基本政治制度。","kao":{"q":"下列属于基本政治制度的是？","options":["人民代表大会制度","民族区域自治制度","宪法制度","司法制度"],"answer":1}},{"id":"p11f","term":"全面依法治国","jieshi":"全面推进依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家；科学立法、严格执法、公正司法、全民守法是全面依法治国的新十六字方针。","kao":{"q":"全面依法治国的新十六字方针是？","options":["有法可依执法必严","科学立法严格执法公正司法全民守法","以德治国","人治为主"],"answer":1}}]},{"id":"p12","title":"高三·哲学与文化·当代国际","grade_tag":"高三","items":[{"id":"p12a","term":"辩证唯物论","jieshi":"物质决定意识，意识对物质具有能动作用；规律是客观的、普遍的，我们要尊重规律、按规律办事，同时发挥主观能动性。","kao":{"q":"物质与意识的关系，正确的是？","options":["意识决定物质","物质决定意识、意识具能动性","二者无关","意识第一性"],"answer":1}},{"id":"p12b","term":"唯物辩证法","jieshi":"联系是普遍的、客观的、多样的；发展是事物的前进和上升；矛盾即对立统一，矛盾的普遍性与特殊性相互联结，要坚持两点论与重点论统一。","kao":{"q":"矛盾的基本属性是？","options":["主要与次要","同一性与斗争性","普遍与特殊","内因与外因"],"answer":1}},{"id":"p12c","term":"认识论","jieshi":"实践是认识的基础（来源、动力、检验标准、目的）；真理是客观的、具体的、有条件的；认识具有反复性、无限性和上升性。","kao":{"q":"实践是认识的？","options":["唯一来源","无关因素","终点","障碍"],"answer":0}},{"id":"p12d","term":"文化传承与创新","jieshi":"文化在继承的基础上发展，在发展的过程中继承；文化创新要立足社会实践，继承传统、推陈出新，面向世界、博采众长。","kao":{"q":"文化创新的立足点是？","options":["书本知识","社会实践","外来文化","主观想象"],"answer":1}},{"id":"p12e","term":"经济全球化","jieshi":"经济全球化使各国经济相互联系、相互依赖程度加深；既是机遇也是挑战；我国坚持对外开放，推动建设开放型世界经济。","kao":{"q":"面对经济全球化，我国应？","options":["闭关锁国","坚持对外开放、趋利避害","全盘西化","退出世界市场"],"answer":1}},{"id":"p12f","term":"国际组织","jieshi":"国际组织是国际社会的基石之外的重要行为主体；联合国是最具普遍性、代表性和权威性的政府间国际组织，其宗旨是维护国际和平与安全、促进国际合作。","kao":{"q":"联合国的最具代表性政府间国际组织性质体现在？","options":["只对西方负责","普遍代表性、权威性","军事同盟","经济组织"],"answer":1}}]}]}}};
