var politics_link_default = {"units":[{"id":"pl1","title":"宪法专题·根本法与公民生活","grade_tag":"八年级/九年级","summary":"系统梳理宪法的地位、基本原则与公民权利义务，配套小测巩固。","points":[{"h":"宪法是国家的根本法","body":"宪法规定国家最根本、最重要的问题，具有最高法律效力，是一切组织和个人的根本活动准则；宪法的修改程序比普通法律更严格。","eg":"例：其他法律不得与宪法相抵触，否则无效。","tip":"💡 区分“根本法”与“基本法”，宪法是根本法。"},{"h":"宪法的基本原则","body":"包括党的领导、人民主权、尊重和保障人权、民主集中制、权力监督和制约等原则。","eg":"例：国家的一切权力属于人民，体现人民主权原则。","tip":"💡 人权入宪是我国法治进步的重要标志。"},{"h":"公民的基本权利与义务","body":"权利与义务相统一：既要依法行使权利，也要自觉履行义务；不得损害国家、社会、集体和他人合法利益。","eg":"例：依法纳税、服兵役是公民基本义务。","tip":"💡 没有无义务的权利，也没有无权利的义务。"}],"quiz":[{"id":"pl1q1","stem":"宪法在国家法律体系中具有（）","options":["普通地位","最高法律地位与效力","可有可无","只约束公民"],"answer":1,"analysis":"宪法是根本法，具有最高法律地位、权威和效力。"},{"id":"pl1q2","stem":"宪法的修改程序（）","options":["与普通法律相同","比普通法律更严格","无需程序","由个人决定"],"answer":1,"analysis":"宪法修改程序更为严格，以维护其稳定性与权威性。"},{"id":"pl1q3","stem":"权利与义务的关系是（）","options":["对立","相统一","无关","只讲权利"],"answer":1,"analysis":"公民的权利与义务是统一的，不可分离。"}]},{"id":"pl2","title":"改革开放与共同富裕","grade_tag":"九年级/高一","summary":"理解改革开放的历史意义与共同富裕的科学内涵，澄清常见误区。","points":[{"h":"改革开放的历史意义","body":"改革开放是决定当代中国命运的关键抉择，极大解放和发展了社会生产力，是强国之路、富民之路。","eg":"例：四十多年间我国国内生产总值跃居世界第二。","tip":"💡 改革开放只有进行时，没有完成时。"},{"h":"共同富裕的科学内涵","body":"共同富裕是中国特色社会主义的本质要求，不是同步富裕、同等富裕，而是全体人民通过辛勤劳动逐步实现的共同富裕。","eg":"例：先富带动后富，最终实现共富。","tip":"💡 允许合理差距，反对平均主义。"},{"h":"共享发展理念","body":"坚持发展为了人民、发展依靠人民、发展成果由人民共享，使全体人民在共建共享中有更多获得感。","eg":"例：脱贫攻坚、基本公共服务均等化。","tip":"💡 共享是高质量发展的根本目的。"}],"quiz":[{"id":"pl2q1","stem":"改革开放是（）","options":["权宜之计","决定当代中国命运的关键抉择","导致贫穷","临时政策"],"answer":1,"analysis":"改革开放是强国之路、关键抉择。"},{"id":"pl2q2","stem":"共同富裕是指（）","options":["同步同时富裕","全体人民共享、逐步共富","部分人独富","平均主义"],"answer":1,"analysis":"共同富裕是逐步实现的全体人民共享发展成果。"},{"id":"pl2q3","stem":"共享发展理念的根本目的是（）","options":["提高效率","让人民共享发展成果","扩大差距","减少生产"],"answer":1,"analysis":"共享发展以增进人民福祉、实现共同富裕为出发点和落脚点。"}]},{"id":"pl3","title":"人民当家作主的制度体系","grade_tag":"九年级/高二","summary":"厘清根本政治制度与基本政治制度的区别与联系，建立制度自信。","points":[{"h":"根本政治制度：人民代表大会制度","body":"人民代表大会制度是我国的根本政治制度，是人民掌握国家政权、行使权力的根本途径，保证人民当家作主。","eg":"例：全国人大是国家最高权力机关。","tip":"💡 根本政治制度只有一项。"},{"h":"基本政治制度（三项）","body":"包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。","eg":"例：村委会、居委会是基层群众自治组织。","tip":"💡 不要把“基本政治制度”与“根本政治制度”混淆。"},{"h":"协商民主","body":"协商民主是我国社会主义民主政治的特有形式和独特优势，有事好商量、众人的事情由众人商量。","eg":"例：人民政协是协商民主的重要渠道。","tip":"💡 选举民主与协商民主都是人民民主的实现形式。"}],"quiz":[{"id":"pl3q1","stem":"我国的根本政治制度是（）","options":["政治协商制度","人民代表大会制度","民族区域自治","基层自治"],"answer":1,"analysis":"人民代表大会制度是根本政治制度。"},{"id":"pl3q2","stem":"下列属于基本政治制度的是（）","options":["人民代表大会制度","民族区域自治制度","宪法制度","司法制度"],"answer":1,"analysis":"三项基本政治制度之一。"},{"id":"pl3q3","stem":"社会主义民主政治的特有形式是（）","options":["协商民主","独裁","少数服从多数即可","弃权"],"answer":0,"analysis":"协商民主是我国社会主义民主政治的特有形式和独特优势。"}]},{"id":"pl4","title":"哲学基本问题与唯物辩证法","grade_tag":"高三","summary":"把握哲学基本问题、辩证唯物论与唯物辩证法核心范畴，提升哲学思维。","points":[{"h":"哲学的基本问题","body":"思维和存在的关系问题是哲学的基本问题，包括何者为第一性（唯物/唯心）以及思维能否正确认识存在（可知论/不可知论）。","eg":"例：物质第一性属于唯物主义。","tip":"💡 基本问题≠基本矛盾。"},{"h":"辩证唯物论核心","body":"物质决定意识，意识对物质具有能动作用；规律客观普遍，要尊重规律并发挥主观能动性。","eg":"例：按客观规律办事，又积极进取。","tip":"💡 反对唯心主义和形而上学的静止观。"},{"h":"唯物辩证法的矛盾观","body":"矛盾即对立统一；矛盾的普遍性与特殊性相互联结，普遍性寓于特殊性之中；要坚持两点论与重点论相统一。","eg":"例：具体问题具体分析是矛盾特殊性要求。","tip":"💡 矛盾的精髓是普遍性与特殊性关系。"}],"quiz":[{"id":"pl4q1","stem":"哲学的基本问题是（）","options":["物质与意识关系","人与自然的矛盾","生产力与生产关系","知行关系"],"answer":0,"analysis":"思维和存在的关系问题是哲学基本问题。"},{"id":"pl4q2","stem":"矛盾的基本属性是（）","options":["主要与次要","同一性与斗争性","普遍与特殊","内因与外因"],"answer":1,"analysis":"同一性与斗争性是矛盾的基本属性。"},{"id":"pl4q3","stem":"物质与意识的关系，正确的是（）","options":["意识决定物质","物质决定意识、意识具能动性","二者无关","意识第一性"],"answer":1,"analysis":"物质决定意识，意识对物质有能动反作用。"}]},{"id":"pl5","title":"经济全球化与中国应对","grade_tag":"高三","summary":"认识经济全球化的表现与影响，理解我国对外开放与构建人类命运共同体理念。","points":[{"h":"经济全球化的表现","body":"主要表现为生产全球化、贸易全球化和金融全球化；使各国经济相互依赖程度加深。","eg":"例：跨国公司在全球配置生产要素。","tip":"💡 全球化是把双刃剑。"},{"h":"我国的对外开放","body":"坚持对外开放的基本国策，推动建设更高水平开放型经济新体制，奉行互利共赢的开放战略。","eg":"例：共建“一带一路”促进国际合作。","tip":"💡 开放带来进步，封闭必然落后。"},{"h":"构建人类命运共同体","body":"面对全球性挑战，我国倡导构建人类命运共同体，建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。","eg":"例：全球抗疫合作、气候治理。","tip":"💡 体现负责任大国担当。"}],"quiz":[{"id":"pl5q1","stem":"经济全球化的主要表现不包括（）","options":["生产全球化","贸易全球化","金融全球化","闭关锁国"],"answer":3,"analysis":"闭关锁国与全球化相悖。"},{"id":"pl5q2","stem":"我国对外开放的基本国策要求（）","options":["闭关锁国","互利共赢的开放战略","贸易保护","退出世界市场"],"answer":1,"analysis":"我国奉行互利共赢的开放战略。"},{"id":"pl5q3","stem":"构建人类命运共同体的理念体现（）","options":["孤立主义","负责任大国担当","霸权思维","零和博弈"],"answer":1,"analysis":"构建人类命运共同体彰显中国负责任大国担当。"}]}]};
