// === GEOGRAPHY_DEFAULT_START ===
var geography_default = {"sections":{"knowledge":{"groups":[{"id":"g7","title":"七年级·地球与地图","grade_tag":"初一","items":[{"id":"g7a","term":"地球的形状与大小","jieshi":"地球是一个不规则的球体，平均半径约6371千米。地球仪是缩小了的地球模型，经纬网用于确定地表位置。","kao":{"q":"地球的平均半径约为（　）","options":["6371千米","1738千米","5461千米","6357千米"],"answer":0}},{"id":"g7b","term":"经纬线与经纬度","jieshi":"纬线指示东西方向、长度不等，赤道最长；经线指示南北方向、长度相等。纬线0度是赤道，经线0度是本初子午线。","kao":{"q":"纬线长度最长的是（　）","options":["本初子午线","赤道","30度纬线","60度纬线"],"answer":1}},{"id":"g7c","term":"经纬网定位与半球划分","jieshi":"利用经纬度可以确定地表任一点位置。赤道划分南北半球，20度W和160度E划分东西半球。","kao":{"q":"划分东西半球的经度是（　）","options":["0度和180度","20度W和160度E","30度和150度","90度和270度"],"answer":1}},{"id":"g7d","term":"地图三要素","jieshi":"地图三要素是比例尺、方向和图例。比例尺是图上距离与实地距离之比，表示实地距离。","kao":{"q":"地图三要素不包括（　）","options":["比例尺","方向","图例","等高线"],"answer":3}},{"id":"g7e","term":"等高线地形图判读","jieshi":"等高线密集处坡陡、稀疏处坡缓；等高线向海拔高处凸出为山谷，向低处凸出为山脊；等高线闭合中心数值大为山顶。","kao":{"q":"等高线向海拔高处凸出表示（　）","options":["山脊","山谷","鞍部","陡崖"],"answer":1}},{"id":"g7f","term":"地球自转与昼夜交替","jieshi":"地球自西向东自转，周期为24小时。地球不透明不发光，太阳照射使地球表面产生昼夜更替现象。","kao":{"q":"产生昼夜交替的根本原因是（　）","options":["地球公转","地球自转","地球是球体","太阳发光"],"answer":1}},{"id":"g7g","term":"地球公转与四季","jieshi":"地球绕太阳公转，周期365天。公转使太阳直射点在南北回归线之间移动，从而形成四季和昼夜长短变化。","kao":{"q":"地球公转方向是（　）","options":["自东向西","自西向东","自南向北","自北向南"],"answer":1}},{"id":"g7h","term":"海陆分布与大洲大洋","jieshi":"地球表面约71%是海洋、29%是陆地，分七大洲四大洋。亚洲是面积最大洲，太平洋是最大洋。","kao":{"q":"地球表面海洋占比约为（　）","options":["29%","50%","71%","81%"],"answer":2}}]},{"id":"g8","title":"八年级·中国地理","grade_tag":"初二","items":[{"id":"g8a","term":"中国的疆域与人口","jieshi":"我国陆地面积约960万平方千米，陆地居世界第三。人口超过14亿，是人口大国，南北人口密度差异显著。","kao":{"q":"我国陆地面积居世界第（　）位","options":["一","二","三","四"],"answer":2}},{"id":"g8b","term":"三级阶梯地势","jieshi":"我国地势西高东低、呈三级阶梯分布。一二级分界为昆仑山—祁连山—横断山，二三级分界为大兴安岭—太行山—巫山—雪峰山。","kao":{"q":"我国地势的总体特征是（　）","options":["东高西低","西高东低","南高北低","中间高四周低"],"answer":1}},{"id":"g8c","term":"四大高原","jieshi":"青藏高原是世界屋脊；内蒙古高原地面平坦；黄土高原沟壑纵横、水土流失严重；云贵高原喀斯特地貌广布。","kao":{"q":"喀斯特地貌广布的高原是（　）","options":["青藏高原","内蒙古高原","黄土高原","云贵高原"],"answer":3}},{"id":"g8d","term":"季风气候显著","jieshi":"我国是世界上季风气候最显著的国家，夏季风来自太平洋和印度洋，带来丰沛降水。夏季风强弱影响降水多少。","kao":{"q":"我国夏季风主要来自（　）","options":["北冰洋","太平洋和印度洋","大西洋","太平洋和北冰洋"],"answer":1}},{"id":"g8e","term":"秦岭—淮河一线","jieshi":"秦岭—淮河是我国重要地理分界线：一月0度等温线、800毫米年等降水量线、湿润区与半湿润区分界、水田与旱地分界。","kao":{"q":"秦岭—淮河以北的耕地类型主要是（　）","options":["水田","旱地","梯田","坝田"],"answer":1}},{"id":"g8f","term":"四大地理区域","jieshi":"我国划分为北方地区、南方地区、西北地区和青藏地区。划分依据是自然地理特征和人文地理差异。","kao":{"q":"我国四大地理区域中，平均海拔最高的是（　）","options":["北方地区","南方地区","西北地区","青藏地区"],"answer":3}},{"id":"g8g","term":"长江与黄河","jieshi":"长江是我国第一长河，发源于唐古拉山，注入东海；黄河是第二长河，发源于巴颜喀拉山，注入渤海，含沙量大。","kao":{"q":"我国含沙量最大的河流是（　）","options":["长江","珠江","黄河","黑龙江"],"answer":2}},{"id":"g8h","term":"珠江与梯田水稻","jieshi":"珠江是我国南方重要河流，水量丰富。南方低山丘陵适合修筑梯田，是我国水稻主产区。","kao":{"q":"我国南方低山丘陵适合发展的农业是（　）","options":["梯田水稻","戈壁种植","冰川农业","游牧业"],"answer":0}}]},{"id":"g9","title":"九年级·区域地理与地理信息","grade_tag":"初三","items":[{"id":"g9a","term":"因地制宜发展农业","jieshi":"农业要因地制宜：平原适合种植业，草原适合畜牧业，山区适合林业，湖泊适合渔业。","kao":{"q":"因地制宜发展农业的原则是（　）","options":["一律种粮","宜农则农宜林则林宜牧则牧","全部发展工业","只看短期效益"],"answer":1}},{"id":"g9b","term":"工业区位因素","jieshi":"工业区位受原料、能源、交通、市场、科技、劳动力等因素影响。原料导向型工业多靠近原料产地。","kao":{"q":"钢铁工业属于的主要区位类型是（　）","options":["市场导向型","原料导向型","劳动力导向型","技术导向型"],"answer":1}},{"id":"g9c","term":"聚落与城市","jieshi":"聚落由房屋和道路组成，是人类居住活动的场所。城市规模越大，功能越复杂，服务种类越多。","kao":{"q":"城市相比乡村的主要特征是（　）","options":["人口更少","规模更大、功能更复杂","完全没有农业","交通更不便"],"answer":1}},{"id":"g9d","term":"人地关系与可持续发展","jieshi":"人地关系经历采集狩猎、农业文明、工业文明阶段。当代人地关系思想追求人与自然和谐共生。","kao":{"q":"可持续发展的核心要求是（　）","options":["只发展经济","经济与资源环境相协调","优先发展工业","停止一切开发"],"answer":1}},{"id":"g9e","term":"地理信息系统应用","jieshi":"地理信息系统（GIS）用于地理信息查询、分析和模拟，地图是地理信息的基本载体。","kao":{"q":"用于分析城市道路拥堵状况并选择最优路线的技术是（　）","options":["全球定位系统","地理信息系统","遥感技术","数字地球"],"answer":1}},{"id":"g9f","term":"遥感与全球定位系统","jieshi":"遥感（RS）用于大范围、快速获取地表信息；全球定位系统（GPS）用于定位导航；三者合称3S技术。","kao":{"q":"GPS的主要功能是（　）","options":["定位和导航","分析数据","监测灾害","绘制地图"],"answer":0}},{"id":"g9g","term":"自然灾害与防治","jieshi":"常见自然灾害有洪涝、干旱、地震、台风、滑坡泥石流。防治措施因灾而异，重点是监测预警和工程措施。","kao":{"q":"台风带来的灾害主要是（　）","options":["干旱","狂风与暴雨洪涝","沙尘暴","寒潮"],"answer":1}}]},{"id":"g10","title":"高一·宇宙中的地球与地球运动","grade_tag":"高一","items":[{"id":"g10a","term":"太阳系的组成","jieshi":"太阳系由太阳、八大行星及其卫星等天体组成。太阳是太阳系唯一的恒星，质量和体积占太阳系绝大部分。","kao":{"q":"太阳系中唯一的恒星是（　）","options":["地球","月球","太阳","火星"],"answer":2}},{"id":"g10b","term":"太阳辐射与能量","jieshi":"太阳是地球生命之源，太阳辐射能量是地球表层能量的主要来源。太阳活动会影响地球气候与通信。","kao":{"q":"太阳辐射能量是地球表层能量的（　）","options":["唯一来源","主要来源","次要来源","无影响"],"answer":1}},{"id":"g10c","term":"地球的圈层结构","jieshi":"地球外部圈层包括大气圈、水圈、生物圈；内部圈层包括地壳、地幔、地核。地壳与上地幔组成岩石圈。","kao":{"q":"岩石圈包括（　）","options":["地壳和上地幔","地幔和地核","整个地球内部","大气圈和对流层"],"answer":0}},{"id":"g10d","term":"地球运动与黄赤交角","jieshi":"黄赤交角约23.5度，太阳直射点在南北回归线（23.5度）之间往复移动，这是四季和五带划分的根本原因。","kao":{"q":"黄赤交角的度数约为（　）","options":["15度","23.5度","30度","45度"],"answer":1}},{"id":"g10e","term":"晨昏线与昼夜长短","jieshi":"晨昏线是昼半球与夜半球的分界线。纬度越高，昼夜长短变化越明显，极圈内出现极昼极夜现象。","kao":{"q":"出现极昼极夜的最低纬度是（　）","options":["23.5度","40度","66.5度","90度"],"answer":2}},{"id":"g10f","term":"正午太阳高度与影子","jieshi":"正午太阳高度由太阳直射点所在纬度决定。太阳直射某地时该地正午太阳高度为90度，影子为零。","kao":{"q":"当太阳直射赤道时，全球正午太阳高度的分布规律是（　）","options":["由赤道向南北递减","由南北极向赤道递减","全部为90度","全部为0度"],"answer":0}}]},{"id":"g11","title":"高二·大气与陆地环境","grade_tag":"高二","items":[{"id":"g11a","term":"大气的垂直分层","jieshi":"自下而上分为对流层、平流层、高层大气。对流层气温随高度升高而降低，天气现象复杂多变；平流层大气平稳，适于飞行。","kao":{"q":"人类生活活动的对流层，其气温特点是（　）","options":["随高度升高而降低","随高度升高而升高","保持不变","先升后降"],"answer":0}},{"id":"g11b","term":"大气热力作用与保温","jieshi":"大气逆辐射补偿地面辐射损失热量，是大气保温作用的基础，使地表昼夜温差小于晴朗无云情形。","kao":{"q":"近地面大气主要、直接的热源是（　）","options":["太阳辐射","地面辐射","大气逆辐射","地面反射"],"answer":1}},{"id":"g11c","term":"常见天气系统","jieshi":"锋面系统带来降水天气，气旋与反气旋影响气流辐散与辐合。台风是热带海洋上发展的强烈气旋。","kao":{"q":"带来阴雨天气并常伴大风降温的是（　）","options":["冷锋","暖锋","反气旋","高压脊"],"answer":0}},{"id":"g11d","term":"气候类型判读","jieshi":"判读气候类型主要看气温与降水量的组合。地中海气候夏季炎热干燥、冬季温和多雨。","kao":{"q":"夏季炎热干燥、冬季温和多雨的气候类型是（　）","options":["温带季风气候","地中海气候","热带雨林气候","温带海洋性气候"],"answer":1}},{"id":"g11e","term":"岩石圈与地质构造","jieshi":"岩石按成因分岩浆岩、沉积岩、变质岩。地壳运动使岩层断裂错动形成断层，岩层受挤压弯曲形成褶皱。","kao":{"q":"岩层受挤压发生弯曲变形的地质构造是（　）","options":["断层","褶皱","海沟","裂谷"],"answer":1}},{"id":"g11f","term":"外力作用与地貌","jieshi":"风化、侵蚀、搬运、堆积是塑造地表地貌的主要外力作用。流水侵蚀形成沟谷，流水堆积形成冲积平原。","kao":{"q":"黄河下游形成地上河主要是由于（　）","options":["流水侵蚀","流水堆积","风力侵蚀","冰川侵蚀"],"answer":1}},{"id":"g11g","term":"水循环与水资源","jieshi":"水循环连接水圈、大气圈、岩石圈和生物圈。海陆间循环使陆地淡水资源得到更新。","kao":{"q":"使陆地水资源不断更新的水循环类型是（　）","options":["海上内循环","海陆间循环","陆地内循环","蒸发循环"],"answer":1}},{"id":"g11h","term":"植被与自然带","jieshi":"植被是自然环境的指示物。由赤道向两极，植被依次为热带雨林、亚热带常绿林、温带落叶阔叶林、亚寒带针叶林。","kao":{"q":"亚寒带针叶林带主要分布在北半球（　）","options":["低纬地区","中纬地区","高纬地区","赤道地区"],"answer":2}}]},{"id":"g12","title":"高三·人类与地理环境","grade_tag":"高三","items":[{"id":"g12a","term":"人口增长与迁移","jieshi":"人口增长模式由传统型向现代型转变，经历高增长阶段。人口迁移受经济、社会、文化、自然因素影响。","kao":{"q":"当前世界人口增长模式处于（　）","options":["原始低增长","高增长向现代型过渡","零增长","负增长"],"answer":1}},{"id":"g12b","term":"城市化与问题","jieshi":"城市化表现为人口向城市集中、城市规模扩大。城市问题包括环境恶化、交通拥堵、住房紧张等。","kao":{"q":"城市化过程中最突出的问题之一是（　）","options":["人口减少","交通拥堵与住房紧张","环境改善","就业充足"],"answer":1}},{"id":"g12c","term":"农业区位与农业地域类型","jieshi":"农业地域类型包括季风水田农业、商品谷物农业、大牧场放牧业、乳畜业等，各有区位特点。","kao":{"q":"商品谷物农业分布的典型国家是（　）","options":["中国南方","美国","西非","东南亚"],"answer":1}},{"id":"g12d","term":"工业地域联系与集聚","jieshi":"工业集聚可以加强企业间信息交流和技术协作，降低运输费用和能源消耗，进而降低生产成本。","kao":{"q":"工业集聚的主要优势不包括（　）","options":["加强信息交流","降低运输费用","降低生产成本","增加生产成本"],"answer":3}},{"id":"g12e","term":"服务业区位","jieshi":"服务业区位受市场需求、交通便利程度、劳动力素质、政策等影响。 现代服务业靠近市场布局。","kao":{"q":"服务业布局的直接影响因素是（　）","options":["市场需求","矿产储量","海岸线长度","纬度位置"],"answer":0}},{"id":"g12f","term":"交通运输与区位","jieshi":"交通运输线选址要综合考虑自然、社会、经济因素。铁路、高速公路、港口的选线原则各不相同。","kao":{"q":"交通运输线布局的主要社会经济因素是（　）","options":["地形地质","经济与人口","气候","植被"],"answer":1}},{"id":"g12g","term":"区域发展阶段与协调","jieshi":"区域发展经历初期、成长、转型、再生阶段。区域协调发展战略促进东中西、城乡协调发展。","kao":{"q":"我国区域协调发展战略的核心是（　）","options":["只发展东部","统筹东中西、城乡协调发展","只发展西部","取消东部"],"answer":1}},{"id":"g12h","term":"人类面临的环境问题","jieshi":"全球性问题包括气候变化、水资源短缺、荒漠化、生物多样性减少。应对需要国际合作与可持续发展。","kao":{"q":"应对全球性环境问题需要（　）","options":["国际合作与共同行动","各国独立解决","忽视问题","停止发展"],"answer":0}}]}]}}};
