var __vocabCache = null;

// 词库为静态资源（public/vocab.json），经 ASSETS 拉取并缓存，避免打进 Worker bundle。
async function vocabData(env) {
  if (__vocabCache) return __vocabCache;
  const res = await env.ASSETS.fetch(new Request('https://internal/vocab.json'));
  if (!res.ok) throw new Error('vocab.json ' + res.status);
  __vocabCache = await res.json();
  return __vocabCache;
}
__name(vocabData, "vocabData");

var __quizCache = null, __jbookCache = null;

// 静态资源加载：题库/教材属纯静态数据，走 public/*.json，缓存于模块级，避免打进 bundle。
async function extData(env, file, slot) {
  const cache = slot === 'quiz' ? __quizCache : __jbookCache;
  if (cache) return cache;
  const res = await env.ASSETS.fetch(new Request('https://internal/' + file));
  if (!res.ok) throw new Error(file + ' ' + res.status);
  const j = await res.json();
  if (slot === 'quiz') __quizCache = j; else __jbookCache = j;
  return j;
}
__name(extData, "extData");

