      const lvl = (q.get("level") || "p");

      let dataset, TRIAL;

      if (lvl === "m") { dataset = math_middle_default; TRIAL = TRIAL_MM; }

      else if (lvl === "h") { dataset = math_high_default; TRIAL = TRIAL_MH; }

      else { dataset = math_primary_default; TRIAL = TRIAL_MP; }

